// DAILY WORD CATALOGUE — 400 scriptures, one per day, none repeating for 400 days (owner 2026-11-18).
// Home, the home-screen widgets and the Daily Word screen all pick today's entry with the SAME rule
// (dailyIndex: local calendar days since 1 Jan 2024, modulo the list length — lib/widgetSnapshot.verseForDay,
// and the native widgets in P2PWidgets.kt / P2PWidgets.swift). Only TODAY's entry is ever shown: the list is
// never displayed, so each day stays a surprise.
// Verse text: Berean Standard Bible (BSB), public domain — https://berean.bible (fetched from bible.helloao.org).
// Theme + "Today's Instruction": one practical step that stays inside what the verse itself says (drafted for
// P2P editorial review). Generated by a script; edit the source list, not this file, for large changes.
export interface DailyVerse { ref: string; text: string; theme: string; instruction: string }
export const DAILY_VERSE_TRANSLATION = "Berean Standard Bible (public domain)";
export const DAILY_VERSES: DailyVerse[] = [
  { ref: "Matthew 28:19", text: "Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,", theme: "Making disciples", instruction: "Jesus sends every disciple to help others become His disciples, not only to believe but to follow Him. Today, choose one person you know and invite them to read a short Bible passage with you this week." },
  { ref: "John 15:5", text: "I am the vine and you are the branches. The one who remains in Me, and I in him, will bear much fruit. For apart from Me you can do nothing.", theme: "Remaining in Christ", instruction: "Jesus is the vine and we are the branches: our fruit comes from staying connected to Him, not from our own effort. Before your busiest task today, stop for one minute and ask Jesus for His help with that exact task." },
  { ref: "Proverbs 27:17", text: "As iron sharpens iron, so one man sharpens another.", theme: "Growing together", instruction: "Believers grow sharper when they talk honestly with each other, the way iron sharpens iron. Today, send a peer one thing you learned from Scripture this week and ask what they are learning." },
  { ref: "Hebrews 10:24-25", text: "And let us consider how to spur one another on to love and good deeds. Let us not neglect meeting together, as some have made a habit, but let us encourage one another, and all the more as you see the Day approaching.", theme: "Encouragement and fellowship", instruction: "We are told to think about how to stir each other up to love and good works, and not to stop meeting together. Today, message one believer a specific encouragement and agree a time to meet or pray this week." },
  { ref: "Colossians 3:16", text: "Let the word of Christ richly dwell within you as you teach and admonish one another with all wisdom, and as you sing psalms, hymns, and spiritual songs with gratitude in your hearts to God.", theme: "The word dwelling richly", instruction: "Christ's word should live in us so richly that it flows out when we teach, encourage and sing. Today, read Colossians 3 slowly, choose one line, and share it with someone in a message." },
  { ref: "2 Timothy 2:2", text: "And the things that you have heard me say among many witnesses, entrust these to faithful men who will be qualified to teach others as well.", theme: "Passing it on", instruction: "Paul taught Timothy so that Timothy would teach faithful people who could teach others too: four generations of disciples. Today, take one thing you have learned and explain it to someone who can pass it on." },
  { ref: "Acts 2:42", text: "They devoted themselves to the apostles’ teaching and to the fellowship, to the breaking of bread and to prayer.", theme: "A devoted life", instruction: "The first believers kept on with four things: the apostles' teaching, fellowship, breaking bread and prayer. Today, check which of the four you have neglected this week and do that one." },
  { ref: "Genesis 1:1", text: "In the beginning God created the heavens and the earth.", theme: "God the Creator", instruction: "Everything that exists began with God; nothing is outside His making or His rule. Today, look carefully at one thing in creation, a tree, the sky, a child, and thank God for it by name." },
  { ref: "Genesis 1:27", text: "So God created man in His own image; in the image of God He created him; male and female He created them.", theme: "Made in God's image", instruction: "Every human being is made in God's image, so every person carries worth that does not depend on what they can do. Today, treat one person others overlook with real respect, by listening to them or helping them." },
  { ref: "Genesis 12:2", text: "I will make you into a great nation, and I will bless you; I will make your name great, so that you will be a blessing.", theme: "Blessed to bless", instruction: "God blessed Abraham so that Abraham would become a blessing to others. Think of one blessing God has given you, time, skill or money, and use it today to bless one specific person." },
  { ref: "Genesis 50:20", text: "As for you, what you intended against me for evil, God intended for good, in order to accomplish a day like this— to preserve the lives of many people.", theme: "God's good purposes", instruction: "Joseph's brothers meant to harm him, but God used it to save many lives. Write down one painful event from your past and ask God in prayer to show you how He can use it for good." },
  { ref: "Exodus 14:14", text: "The LORD will fight for you; you need only to be still.”", theme: "The Lord fights for you", instruction: "At the Red Sea, Israel could do nothing to save themselves; God fought for them while they stayed calm. Name the problem you cannot fix, pray about it once, and then stop trying to control it today." },
  { ref: "Exodus 20:3", text: "You shall have no other gods before Me.", theme: "God first", instruction: "The first commandment says nothing may take God's place in our hearts. Ask yourself what you think about most when you are free, and give the first ten minutes of your day to God instead." },
  { ref: "Exodus 33:14", text: "And the LORD answered, “My Presence will go with you, and I will give you rest.”", theme: "God's presence", instruction: "Moses would not go forward without God's presence, and God promised it would go with him and give him rest. Before you leave home today, pray: \"Lord, go with me into this day,\" and name where you are going." },
  { ref: "Leviticus 19:18", text: "Do not seek revenge or bear a grudge against any of your people, but love your neighbor as yourself. I am the LORD.", theme: "Loving your neighbour", instruction: "God tells His people not to take revenge or hold a grudge, but to love their neighbour as themselves. If you are holding a grudge, pray for that person by name today and do one kind thing for them." },
  { ref: "Numbers 6:24-26", text: "‘May the LORD bless you and keep you; may the LORD cause His face to shine upon you and be gracious to you; may the LORD lift up His countenance toward you and give you peace.’", theme: "The Lord's blessing", instruction: "God gave the priests these words to place His blessing on His people. Today, pray these three lines over someone you love, putting their name in each line." },
  { ref: "Numbers 23:19", text: "God is not a man, that He should lie, or a son of man, that He should change His mind. Does He speak and not act? Does He promise and not fulfill?", theme: "God keeps His word", instruction: "God is not like people who lie or change their minds; what He has promised, He will do. Write down one promise of God you are waiting on and thank Him today that He will keep it." },
  { ref: "Deuteronomy 6:5", text: "And you shall love the LORD your God with all your heart and with all your soul and with all your strength.", theme: "Wholehearted love", instruction: "God asks for love from the whole person: heart, soul and strength, not just a part of our life. Name one area you have kept back from God, your money, time or a relationship, and give it to Him in prayer." },
  { ref: "Deuteronomy 6:6-7", text: "These words I am commanding you today are to be upon your hearts. And you shall teach them diligently to your children and speak of them when you sit at home and when you walk along the road, when you lie down and when you get up.", theme: "Teaching the next generation", instruction: "God's words were to be on parents' hearts and talked about at home, on the road, at night and in the morning. Today, share one Bible verse with a child or young person in an ordinary moment, at a meal or on a journey." },
  { ref: "Deuteronomy 31:6", text: "Be strong and courageous; do not be afraid or terrified of them, for it is the LORD your God who goes with you; He will never leave you nor forsake you.”", theme: "Strong and courageous", instruction: "Moses told Israel to be strong because God Himself goes with them and will never abandon them. Do one thing today that you have been avoiding out of fear, and pray before you do it." },
  { ref: "Deuteronomy 31:8", text: "The LORD Himself goes before you; He will be with you. He will never leave you nor forsake you. Do not be afraid or discouraged.”", theme: "He goes before you", instruction: "God does not only go with us; He goes ahead of us into places we have not yet reached. Before an appointment or task today, pray: \"Lord, You are already there before me.\"" },
  { ref: "Joshua 1:8", text: "This Book of the Law must not depart from your mouth; meditate on it day and night, so that you may be careful to do everything written in it. For then you will prosper and succeed in all you do.", theme: "Meditating on the Word", instruction: "God told Joshua that success would come from keeping His Word in his mouth and thinking about it day and night. Write one verse on paper or your phone and read it in the morning, at midday and at night." },
  { ref: "Joshua 1:9", text: "Have I not commanded you to be strong and courageous? Do not be afraid; do not be discouraged, for the LORD your God is with you wherever you go.”", theme: "Courage in obedience", instruction: "God commanded Joshua to be courageous because God would be with him everywhere he went. Identify one step of obedience that scares you, and take it today." },
  { ref: "Joshua 24:15", text: "But if it is unpleasing in your sight to serve the LORD, then choose for yourselves this day whom you will serve, whether the gods your fathers served beyond the Euphrates, or the gods of the Amorites in whose land you are living. As for me and my house, we will serve the LORD!”", theme: "Choosing to serve", instruction: "Joshua made a public choice: whatever others did, his household would serve the Lord. Today, say out loud to God, and if you can to your family, that you choose to serve Him." },
  { ref: "Ruth 1:16", text: "But Ruth replied: “Do not urge me to leave you or to turn from following you. For wherever you go, I will go, and wherever you live, I will live; your people will be my people, and your God will be my God.", theme: "Faithful love", instruction: "Ruth chose to stay with Naomi and to make Naomi's God her God, even when it cost her. Call or visit someone who is going through a hard time and tell them you are staying beside them." },
  { ref: "1 Samuel 3:10", text: "Then the LORD came and stood there, calling as before, “Samuel! Samuel!” And Samuel answered, “Speak, for Your servant is listening.”", theme: "Listening to God", instruction: "Young Samuel answered God's call with readiness to listen and obey. Sit quietly for five minutes today, read a short passage, and ask: \"Lord, what are You saying to me?\"" },
  { ref: "1 Samuel 16:7", text: "But the LORD said to Samuel, “Do not consider his appearance or height, for I have rejected him; the LORD does not see as man does. For man sees the outward appearance, but the LORD sees the heart.”", theme: "God looks at the heart", instruction: "People judge by appearance, but God looks at the heart. Today, catch yourself when you judge someone by how they look, and ask God to show you their heart instead." },
  { ref: "1 Samuel 17:47", text: "And all those assembled here will know that it is not by sword or spear that the LORD saves; for the battle is the LORD’s, and He will give all of you into our hands.”", theme: "The battle is the Lord's", instruction: "David faced Goliath knowing the victory belonged to God, not to weapons. Name your \"giant\" today and pray specifically about it, telling God you trust Him with the outcome." },
  { ref: "2 Samuel 22:31", text: "As for God, His way is perfect; the word of the LORD is flawless. He is a shield to all who take refuge in Him.", theme: "God's perfect way", instruction: "David sang that God's way is perfect and His word is proven true. Think of a situation you do not understand, and tell God in prayer that you still trust His way in it." },
  { ref: "1 Kings 19:12", text: "After the earthquake there was a fire, but the LORD was not in the fire. And after the fire came a still, small voice.", theme: "The gentle whisper", instruction: "After wind, earthquake and fire, God spoke to Elijah in a gentle whisper. Turn off your phone for ten minutes today, read a Psalm, and listen in the quiet." },
  { ref: "2 Kings 6:16", text: "“Do not be afraid,” Elisha answered, “for those who are with us are more than those who are with them.”", theme: "Those with us", instruction: "Elisha's servant saw only the enemy army, but Elisha knew God's army was greater. When you feel outnumbered today, pray: \"Lord, open my eyes to see Your help.\"" },
  { ref: "1 Chronicles 16:11", text: "Seek out the LORD and His strength; seek His face always.", theme: "Seeking His face", instruction: "David called Israel to seek the Lord and His strength continually, not only in emergencies. Set two alarms today, morning and evening, and pray for two minutes each time." },
  { ref: "1 Chronicles 16:34", text: "Give thanks to the LORD, for He is good; His loving devotion endures forever.", theme: "Thanksgiving", instruction: "We thank God because He is good and His faithful love never ends. Write down three specific things God gave you this week and thank Him for each by name." },
  { ref: "2 Chronicles 7:14", text: "and if My people who are called by My name humble themselves and pray and seek My face and turn from their wicked ways, then I will hear from heaven, forgive their sin, and heal their land.", theme: "Humble prayer", instruction: "God promised to hear, forgive and heal when His people humble themselves, pray and turn from wrong. Pray today for your town or nation, and confess one wrong in your own life first." },
  { ref: "Ezra 7:10", text: "For Ezra had set his heart to study the Law of the LORD, to practice it, and to teach its statutes and ordinances in Israel.", theme: "Study, practise, teach", instruction: "Ezra set his heart first to study God's law, then to do it, then to teach it, in that order. Today, study one short passage, choose one thing to obey from it, and share it with one person." },
  { ref: "Nehemiah 8:10", text: "Then Nehemiah told them, “Go and eat what is rich, drink what is sweet, and send out portions to those who have nothing prepared, since today is holy to our Lord. Do not grieve, for the joy of the LORD is your strength.”", theme: "The joy of the Lord", instruction: "When the people wept over their sin, Nehemiah told them God's joy would be their strength. If you feel weak or guilty today, thank God for His forgiveness and let that joy carry you." },
  { ref: "Esther 4:14", text: "For if you remain silent at this time, relief and deliverance for the Jews will arise from another place, but you and your father’s house will perish. And who knows if perhaps you have come to the kingdom for such a time as this?”", theme: "For such a time as this", instruction: "Esther realised she had been placed in the palace for a purpose: to speak up for her people. Ask yourself who God has placed you near, at work, school or home, and speak up for someone who needs help." },
  { ref: "Job 19:25", text: "But I know that my Redeemer lives, and in the end He will stand upon the earth.", theme: "My Redeemer lives", instruction: "In the middle of great loss, Job held on to this: his Redeemer is alive and will stand at the end. If you are suffering, say these words aloud today: \"I know that my Redeemer lives.\"" },
  { ref: "Job 42:2", text: "“I know that You can do all things and that no plan of Yours can be thwarted.", theme: "Nothing too hard", instruction: "After meeting God, Job confessed that no plan of God can be stopped. Bring the situation that feels impossible to God today and tell Him plainly that you believe He can do it." },
  { ref: "Psalms 1:1-2", text: "Blessed is the man who does not walk in the counsel of the wicked, or set foot on the path of sinners, or sit in the seat of mockers. But his delight is in the Law of the LORD, and on His law he meditates day and night.", theme: "Delighting in God's law", instruction: "The blessed person avoids the advice of the wicked and delights in God's law, thinking about it day and night. Choose one verse this morning and come back to it at least twice before bedtime." },
  { ref: "Psalms 4:8", text: "I will lie down and sleep in peace, for You alone, O LORD, make me dwell in safety.", theme: "Peaceful rest", instruction: "David could sleep in peace because the Lord kept him safe, not because his troubles were gone. Tonight, name your worries to God one by one before you sleep and leave them with Him." },
  { ref: "Psalms 5:3", text: "In the morning, O LORD, You hear my voice; at daybreak I lay my plea before You and wait in expectation.", theme: "Morning prayer", instruction: "David brought his requests to God in the morning and then watched expectantly for God's answer. Tomorrow morning, write one specific request, pray it, and look for God's answer during the day." },
  { ref: "Psalms 8:3-4", text: "When I behold Your heavens, the work of Your fingers, the moon and the stars, which You have set in place — what is man that You are mindful of him, or the son of man that You care for him?", theme: "Wonder at God", instruction: "Looking at the stars, David wondered why the great Creator cares for small people. Go outside tonight, look at the sky, and thank God that He knows and cares for you personally." },
  { ref: "Psalms 16:8", text: "I have set the LORD always before me. Because He is at my right hand, I will not be shaken.", theme: "The Lord before me", instruction: "David kept the Lord always before him, so he would not be shaken. Before every decision today, big or small, pause and ask, \"Lord, what pleases You here?\"" },
  { ref: "Psalms 16:11", text: "You have made known to me the path of life; You will fill me with joy in Your presence, with eternal pleasures at Your right hand.", theme: "Fullness of joy", instruction: "True joy and lasting pleasure are found in God's presence. Spend fifteen minutes today simply enjoying God, reading a Psalm of praise or singing, without asking for anything." },
  { ref: "Psalms 18:2", text: "The LORD is my rock, my fortress, and my deliverer. My God is my rock, in whom I take refuge, my shield, and the horn of my salvation, my stronghold.", theme: "My rock", instruction: "David described God as his rock, fortress and deliverer: the place where he was safe. Name what you usually run to when afraid, and today run to God in prayer first instead." },
  { ref: "Psalms 19:1", text: "For the choirmaster. A Psalm of David. The heavens declare the glory of God; the skies proclaim the work of His hands.", theme: "Creation declares", instruction: "The heavens tell of God's glory without speaking a word. Today, notice one thing in nature and tell someone what it shows you about God." },
  { ref: "Psalms 19:14", text: "May the words of my mouth and the meditation of my heart be pleasing in Your sight, O LORD, my Rock and my Redeemer.", theme: "Words and thoughts", instruction: "David asked that both his words and his private thoughts would please God. Pray this verse before your first conversation today, and notice one word you need to hold back." },
  { ref: "Psalms 23:1", text: "A Psalm of David. The LORD is my shepherd; I shall not want.", theme: "The Lord my shepherd", instruction: "Because the Lord is our shepherd, we lack nothing we truly need. List three needs God met for you this month and thank Him for His care." },
  { ref: "Psalms 23:4", text: "Even though I walk through the valley of the shadow of death, I will fear no evil, for You are with me; Your rod and Your staff, they comfort me.", theme: "No fear in the valley", instruction: "Even in the darkest valley, the shepherd is with his sheep, so we do not need to fear evil. If you are in a dark season, tell God about it honestly today and thank Him that He is with you in it." },
  { ref: "Psalms 25:4-5", text: "Show me Your ways, O LORD; teach me Your paths. Guide me in Your truth and teach me, for You are the God of my salvation; all day long I wait for You.", theme: "Teach me Your ways", instruction: "David asked God to teach him His paths, because he hoped in God all day. Choose one decision you face, and ask God to teach you His way in it before you decide." },
  { ref: "Psalms 27:1", text: "Of David. The LORD is my light and my salvation— whom shall I fear? The LORD is the stronghold of my life— whom shall I dread?", theme: "The Lord my light", instruction: "If the Lord is our light and salvation, no person or situation should rule us through fear. Name your biggest fear today and say this verse aloud over it." },
  { ref: "Psalms 27:14", text: "Wait patiently for the LORD; be strong and courageous. Wait patiently for the LORD!", theme: "Waiting on the Lord", instruction: "Waiting on the Lord takes strength and courage; it is trusting, not giving up. Where you are waiting for an answer, pray about it today and choose not to force it." },
  { ref: "Psalms 32:8", text: "I will instruct you and teach you the way you should go; I will give you counsel and watch over you.", theme: "God's guidance", instruction: "God promises to instruct us and guide us with His eye on us. Ask God for guidance in one specific choice today, then read a passage and pay attention to what it says." },
  { ref: "Psalms 34:8", text: "Taste and see that the LORD is good; blessed is the man who takes refuge in Him!", theme: "Taste and see", instruction: "David invites us to experience God's goodness for ourselves, like tasting food. Tell one person today about a specific time God was good to you." },
  { ref: "Psalms 34:18", text: "The LORD is near to the brokenhearted; He saves the contrite in spirit.", theme: "Near the broken-hearted", instruction: "The Lord is especially close to people whose hearts are broken. Reach out today to someone who is grieving or hurting, and simply be with them or pray for them." },
  { ref: "Psalms 37:4", text: "Delight yourself in the LORD, and He will give you the desires of your heart.", theme: "Delight in the Lord", instruction: "When God Himself is our delight, our desires begin to match His. Spend time today thanking God for who He is, His character, before you ask Him for anything." },
  { ref: "Psalms 37:5", text: "Commit your way to the LORD; trust in Him, and He will do it.", theme: "Commit your way", instruction: "To commit our way to the Lord is to hand over our plans and trust Him to act. Write your plans for today, pray over them, and hold them loosely if God changes them." },
  { ref: "Psalms 42:11", text: "Why are you downcast, O my soul? Why the unease within me? Put your hope in God, for I will yet praise Him, my Savior and my God.", theme: "Hope in God", instruction: "The psalmist talks to his own discouraged soul and tells it to hope in God. If you feel low today, speak to yourself: \"Why are you downcast? Put your hope in God,\" and name one reason to praise Him." },
  { ref: "Psalms 46:1", text: "For the choirmaster. Of the sons of Korah. According to Alamoth. A song. God is our refuge and strength, an ever-present help in times of trouble.", theme: "Our refuge", instruction: "God is a refuge we can run to and a help that is always present in trouble. When trouble comes today, pray before you phone anyone or make a plan." },
  { ref: "Psalms 46:10", text: "“Be still and know that I am God; I will be exalted among the nations, I will be exalted over the earth.”", theme: "Be still", instruction: "God tells His people to stop striving and recognise that He is God. Sit still for five minutes today, with no phone or list, and simply remember who God is." },
  { ref: "Psalms 51:10", text: "Create in me a clean heart, O God, and renew a right spirit within me.", theme: "A clean heart", instruction: "After his sin with Bathsheba, David asked God to create a clean heart in him. Confess one specific sin to God today, and ask Him to change your heart, not only your behaviour." },
  { ref: "Psalms 55:22", text: "Cast your burden upon the LORD and He will sustain you; He will never let the righteous be shaken.", theme: "Casting your burden", instruction: "We are told to throw our burdens on the Lord, and He will sustain us. Write down the burden that weighs on you most, pray over it, and then tear up the paper as a sign you have given it to Him." },
  { ref: "Psalms 56:3", text: "When I am afraid, I put my trust in You.", theme: "Trust in fear", instruction: "David did not say he never felt afraid; he said that when he was afraid, he would trust God. Each time fear rises today, say quietly, \"When I am afraid, I will trust in You.\"" },
  { ref: "Psalms 62:1-2", text: "For the choirmaster. According to Jeduthun. A Psalm of David. In God alone my soul finds rest; my salvation comes from Him. He alone is my rock and my salvation. He is my fortress; I will never be shaken.", theme: "Rest in God alone", instruction: "David found rest for his soul in God alone, not in people or success. Notice where you look for security today, and tell God He is your rock instead." },
  { ref: "Psalms 63:1", text: "A Psalm of David, when he was in the Wilderness of Judah. O God, You are my God. Earnestly I seek You; my soul thirsts for You. My body yearns for You in a dry and weary land without water.", theme: "Thirsting for God", instruction: "In the desert, David longed for God like a thirsty man longs for water. Tell God honestly today what you are thirsty for, and spend time in His Word before reaching for anything else." },
  { ref: "Psalms 73:26", text: "My flesh and my heart may fail, but God is the strength of my heart and my portion forever.", theme: "God my portion", instruction: "Our body and heart may fail, but God remains our strength and our portion forever. If you feel weak today, thank God that He is your strength, and ask Him for help with one specific task." },
  { ref: "Psalms 84:10", text: "For better is one day in Your courts than a thousand elsewhere. I would rather be a doorkeeper in the house of my God than dwell in the tents of the wicked.", theme: "Better is one day", instruction: "One day near God is better than a thousand days anywhere else. Make time today to be with God's people, in a gathering, call or group, and treat it as a privilege." },
  { ref: "Psalms 86:11", text: "Teach me Your way, O LORD, that I may walk in Your truth. Give me an undivided heart, that I may fear Your name.", theme: "An undivided heart", instruction: "David asked for an undivided heart, a heart not split between God and other things. Name one thing that divides your heart, and ask God to help you put Him first in it today." },
  { ref: "Psalms 90:12", text: "So teach us to number our days, that we may present a heart of wisdom.", theme: "Numbering our days", instruction: "Moses prayed for God to teach us how short life is, so we live wisely. Look at how you spent yesterday, and choose one thing today that will matter for eternity." },
  { ref: "Psalms 91:1-2", text: "He who dwells in the shelter of the Most High will abide in the shadow of the Almighty. I will say to the LORD, “You are my refuge and my fortress, my God, in whom I trust.”", theme: "Shelter of the Most High", instruction: "Whoever lives close to God finds shelter and safety in Him. Begin today by saying aloud, \"Lord, You are my refuge and my fortress; I trust You,\" before you leave home." },
  { ref: "Psalms 95:6", text: "O come, let us worship and bow down; let us kneel before the LORD our Maker.", theme: "Worship", instruction: "Worship includes humbling ourselves, even bowing before the Lord our Maker. Kneel or bow for a few minutes today and worship God as your Creator." },
  { ref: "Psalms 100:4", text: "Enter His gates with thanksgiving and His courts with praise; give thanks to Him and bless His name.", theme: "Enter with thanks", instruction: "We come into God's presence with thanksgiving and praise first. In your prayer today, spend the first minutes only thanking Him, and ask for things afterwards." },
  { ref: "Psalms 103:2-3", text: "Bless the LORD, O my soul, and do not forget all His kind deeds — He who forgives all your iniquities and heals all your diseases,", theme: "Forget not His benefits", instruction: "David tells his soul not to forget God's benefits: forgiveness, healing and much more. List five things God has done for you and read the list back to Him in thanks." },
  { ref: "Psalms 103:12", text: "As far as the east is from the west, so far has He removed our transgressions from us.", theme: "Sins removed", instruction: "God removes our confessed sins as far as the east is from the west, completely. If you still feel guilty about sin you have confessed, thank God aloud today that it is gone." },
  { ref: "Psalms 107:1", text: "Give thanks to the LORD, for He is good; His loving devotion endures forever.", theme: "His love endures", instruction: "God's goodness and faithful love do not run out. Thank God today for one way He has been faithful to you over many years." },
  { ref: "Psalms 118:24", text: "This is the day that the LORD has made; we will rejoice and be glad in it.", theme: "This is the day", instruction: "Each day is made by the Lord, so we can choose to rejoice in it. When something goes wrong today, say: \"This is still the day the Lord has made,\" and thank Him for one thing in it." },
  { ref: "Psalms 119:11", text: "I have hidden Your word in my heart that I might not sin against You.", theme: "Hidden in the heart", instruction: "Storing God's Word in our heart helps us not to sin against Him. Memorise this verse today, and say it when temptation comes." },
  { ref: "Psalms 119:105", text: "Your word is a lamp to my feet and a light to my path.", theme: "A lamp for my feet", instruction: "God's Word lights up the next step, like a lamp in the dark. Before a decision today, read a passage related to it and ask what it shows you." },
  { ref: "Psalms 121:1-2", text: "A song of ascents. I lift up my eyes to the hills. From where does my help come? My help comes from the LORD, the Maker of heaven and earth.", theme: "Help from the Lord", instruction: "Help does not come from the hills or from people, but from the Lord who made heaven and earth. When you need help today, pray to the Lord before you look anywhere else." },
  { ref: "Psalms 126:5", text: "Those who sow in tears will reap with shouts of joy.", theme: "Sowing in tears", instruction: "Those who sow seed with tears will harvest with joy; faithful work in hard times bears fruit. Keep doing one good thing today that feels hard or unseen, trusting God for the harvest." },
  { ref: "Psalms 127:1", text: "A song of ascents. Of Solomon. Unless the LORD builds the house, its builders labor in vain; unless the LORD protects the city, its watchmen stand guard in vain.", theme: "Unless the Lord builds", instruction: "Unless the Lord builds the house, the builders work in vain. Pray over your work, home and family today, asking God to build what you cannot." },
  { ref: "Psalms 133:1", text: "A song of ascents. Of David. Behold, how good and pleasant it is when brothers live together in harmony!", theme: "Living in unity", instruction: "It is good and pleasant when God's people live together in unity. Make peace today with a believer you have had tension with, or speak well of them to others." },
  { ref: "Psalms 139:14", text: "I praise You, for I am fearfully and wonderfully made. Marvelous are Your works, and I know this very well.", theme: "Wonderfully made", instruction: "God made you carefully and wonderfully. Thank God today for one thing about how He made you that you have struggled to accept." },
  { ref: "Psalms 139:23-24", text: "Search me, O God, and know my heart; test me and know my concerns. See if there is any offensive way in me; lead me in the way everlasting.", theme: "Search me", instruction: "David invited God to search his heart and point out anything offensive. Sit quietly today and pray this verse; write down anything God brings to mind and deal with it." },
  { ref: "Psalms 143:8", text: "Let me hear Your loving devotion in the morning, for I have put my trust in You. Teach me the way I should walk, for to You I lift up my soul.", theme: "Morning trust", instruction: "David asked to hear of God's love in the morning and to be shown which way to go. Tomorrow morning, before your phone, read a Psalm and ask God for direction for the day." },
  { ref: "Psalms 145:18", text: "The LORD is near to all who call on Him, to all who call out to Him in truth.", theme: "God is near", instruction: "The Lord is near to everyone who calls on Him in truth, honestly. Pray today without fine words, telling God exactly how you feel." },
  { ref: "Psalms 147:3", text: "He heals the brokenhearted and binds up their wounds.", theme: "He heals the broken", instruction: "God heals the broken-hearted and binds up their wounds like a doctor. Bring one specific hurt to God today and ask Him to begin healing it." },
  { ref: "Psalms 150:6", text: "Let everything that has breath praise the LORD! Hallelujah!", theme: "Praise the Lord", instruction: "Everything that has breath should praise the Lord. Spend five minutes today praising God aloud, in song or spoken words, for who He is." },
  { ref: "Proverbs 3:5-6", text: "Trust in the LORD with all your heart, and lean not on your own understanding; in all your ways acknowledge Him, and He will make your paths straight.", theme: "Trusting God's direction", instruction: "Trusting the Lord with all our heart means not leaning on our own understanding when we decide. Name one decision you face, ask God about it in prayer, and wait for peace before you act." },
  { ref: "Proverbs 3:9", text: "Honor the LORD with your wealth and with the firstfruits of all your crops;", theme: "Honouring God with what you have", instruction: "We honour God by giving Him the first and best of what we earn, not what is left over. Decide today what portion of your next income you will give to God first." },
  { ref: "Proverbs 4:23", text: "Guard your heart with all diligence, for from it flow springs of life.", theme: "Guarding the heart", instruction: "The heart is the source of our whole life, so it needs guarding. Notice what you watch, read and listen to today, and remove one thing that pulls your heart away from God." },
  { ref: "Proverbs 11:25", text: "A generous soul will prosper, and he who refreshes others will himself be refreshed.", theme: "Generosity", instruction: "Those who refresh others will themselves be refreshed. Give something today, a meal, money or your time, to someone who needs it." },
  { ref: "Proverbs 12:25", text: "Anxiety weighs down the heart of a man, but a good word cheers it up.", theme: "A kind word", instruction: "Anxiety weighs the heart down, but a kind word lifts it. Find someone today who looks worried and give them a sincere word of encouragement." },
  { ref: "Proverbs 15:1", text: "A gentle answer turns away wrath, but a harsh word stirs up anger.", theme: "A gentle answer", instruction: "A gentle answer calms anger, while harsh words make it worse. In the next tense conversation, lower your voice and answer gently on purpose." },
  { ref: "Proverbs 16:3", text: "Commit your works to the LORD and your plans will be achieved.", theme: "Committing your work", instruction: "Committing our work to the Lord means doing it for Him and trusting Him with the results. Before you start work today, pray over each task on your list by name." },
  { ref: "Proverbs 16:9", text: "A man’s heart plans his course, but the LORD determines his steps.", theme: "God directs our steps", instruction: "We make plans, but the Lord directs where our steps actually go. Plan your day, then pray, \"Lord, change these plans if You want to,\" and accept interruptions as from Him." },
  { ref: "Proverbs 17:17", text: "A friend loves at all times, and a brother is born for adversity.", theme: "A true friend", instruction: "A true friend loves at all times, and is especially there in hard times. Contact a friend who is struggling today, and ask how you can practically help." },
  { ref: "Proverbs 18:10", text: "The name of the LORD is a strong tower; the righteous run to it and are safe.", theme: "A strong tower", instruction: "The name of the Lord is a strong tower where the righteous run to be safe. When you feel attacked or afraid today, call on the name of Jesus in prayer before reacting." },
  { ref: "Proverbs 22:6", text: "Train up a child in the way he should go, and when he is old he will not depart from it.", theme: "Training the young", instruction: "What children are trained in when young shapes the way they walk later. Spend time this week teaching a child one Bible story or verse, and explain what it means." },
  { ref: "Proverbs 27:1", text: "Do not boast about tomorrow, for you do not know what a day may bring.", theme: "Today, not tomorrow", instruction: "We do not know what tomorrow will bring, so we should not boast about it. Do today the good thing you have been postponing: the call, the apology or the visit." },
  { ref: "Proverbs 31:30", text: "Charm is deceptive and beauty is fleeting, but a woman who fears the LORD is to be praised.", theme: "Fearing the Lord", instruction: "Charm and beauty fade, but a person who fears the Lord is truly praiseworthy. Praise someone today for their faithfulness to God, not for their looks or success." },
  { ref: "Ecclesiastes 3:1", text: "To everything there is a season, and a time for every purpose under heaven:", theme: "A time for everything", instruction: "God has set a right time for every activity under heaven. Ask God what this season of your life is for, and stop resenting what it is not." },
  { ref: "Ecclesiastes 4:9-10", text: "Two are better than one, because they have a good return for their labor. For if one falls down, his companion can lift him up; but pity the one who falls without another to help him up!", theme: "Two are better than one", instruction: "Two are better than one, because when one falls the other can help them up. Check on your study partner or a friend today and ask if they need help with anything." },
  { ref: "Ecclesiastes 12:1", text: "Remember your Creator in the days of your youth, before the days of adversity come and the years approach of which you will say, “I find no pleasure in them,”", theme: "Remember your Creator", instruction: "We are called to remember our Creator while we are young and strong, not to wait until later. Give God your best energy today by praying and reading before you are tired." },
  { ref: "Song of Solomon 8:7", text: "Mighty waters cannot quench love; rivers cannot sweep it away. If a man were to give all the wealth of his house for love, his offer would be utterly scorned.", theme: "Love that lasts", instruction: "True love is so strong that floods cannot put it out, and money cannot buy it. Show love today to your spouse, family member or friend in a way that costs you time, not money." },
  { ref: "Isaiah 6:8", text: "Then I heard the voice of the Lord saying: “Whom shall I send? Who will go for Us?” And I said: “Here am I. Send me!”", theme: "Here am I", instruction: "When Isaiah heard God ask, \"Whom shall I send?\" he answered, \"Here am I. Send me!\" Pray this answer today, and do the first thing that comes to mind to serve someone." },
  { ref: "Isaiah 9:6", text: "For unto us a child is born, unto us a son is given, and the government will be upon His shoulders. And He will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.", theme: "The Prince of Peace", instruction: "Jesus is the Wonderful Counsellor, Mighty God, Everlasting Father and Prince of Peace. Bring one troubled situation to Jesus today and ask Him to be your counsellor in it." },
  { ref: "Isaiah 26:3", text: "You will keep in perfect peace the steadfast of mind, because he trusts in You.", theme: "Perfect peace", instruction: "God keeps in perfect peace those whose minds stay fixed on Him because they trust Him. When an anxious thought comes today, replace it with one truth about God." },
  { ref: "Isaiah 40:8", text: "The grass withers and the flowers fall, but the word of our God stands forever.”", theme: "The Word stands forever", instruction: "Grass withers and flowers fade, but the word of our God stands forever. Choose one promise from Scripture to build your day on instead of the news or your feelings." },
  { ref: "Isaiah 40:29", text: "He gives power to the faint and increases the strength of the weak.", theme: "Strength for the weary", instruction: "God gives strength to the weary and power to those who are weak. If you are exhausted, tell God plainly today and ask Him for strength for one specific task." },
  { ref: "Isaiah 40:31", text: "But those who wait upon the LORD will renew their strength; they will mount up with wings like eagles; they will run and not grow weary, they will walk and not faint.", theme: "Renewed strength", instruction: "Those who wait on the Lord will have their strength renewed, like eagles rising on the wind. Before rushing into today, spend ten unhurried minutes waiting on God in prayer." },
  { ref: "Isaiah 41:10", text: "Do not fear, for I am with you; do not be afraid, for I am your God. I will strengthen you; I will surely help you; I will uphold you with My righteous right hand.", theme: "Do not fear", instruction: "God tells us not to fear because He is with us, will strengthen us and hold us up. Write this verse on a card and read it every time you feel afraid today." },
  { ref: "Isaiah 43:2", text: "When you pass through the waters, I will be with you; and when you go through the rivers, they will not overwhelm you. When you walk through the fire, you will not be scorched; the flames will not set you ablaze.", theme: "Through the waters", instruction: "God does not promise we will avoid deep waters, but that He will be with us through them. Name the hardship you are passing through, and thank God that you are not alone in it." },
  { ref: "Isaiah 43:19", text: "Behold, I am about to do something new; even now it is coming. Do you not see it? Indeed, I will make a way in the wilderness and streams in the desert.", theme: "A new thing", instruction: "God says He is doing something new, like a road in the wilderness. Ask God to show you one new thing He is doing in your life, and watch for it this week." },
  { ref: "Isaiah 53:5", text: "But He was pierced for our transgressions, He was crushed for our iniquities; the punishment that brought us peace was upon Him, and by His stripes we are healed.", theme: "Healed by His wounds", instruction: "Jesus was pierced and crushed for our sins, and by His wounds we are healed. Read Isaiah 53 today and thank Jesus specifically for the punishment He took for you." },
  { ref: "Isaiah 53:6", text: "We all like sheep have gone astray, each one has turned to his own way; and the LORD has laid upon Him the iniquity of us all.", theme: "The Lord laid on Him", instruction: "We have all wandered like sheep, and God laid all our sin on Jesus. Name one way you have gone your own way, confess it, and thank God that Jesus carried it." },
  { ref: "Isaiah 55:6", text: "Seek the LORD while He may be found; call on Him while He is near.", theme: "Seek the Lord", instruction: "We are urged to seek the Lord while He may be found, and not delay. If you have been putting off time with God, set aside twenty minutes today and keep it." },
  { ref: "Isaiah 55:8-9", text: "“For My thoughts are not your thoughts, neither are your ways My ways,” declares the LORD. “For as the heavens are higher than the earth, so My ways are higher than your ways and My thoughts than your thoughts.", theme: "Higher ways", instruction: "God's thoughts and ways are higher than ours, as the heavens are higher than the earth. Where you do not understand what God is doing, tell Him today: \"I trust Your higher ways.\"" },
  { ref: "Isaiah 55:11", text: "so My word that proceeds from My mouth will not return to Me empty, but it will accomplish what I please, and it will prosper where I send it.", theme: "The Word does its work", instruction: "God's word does not return empty; it accomplishes what He intends. Send one verse today to someone who needs it, and trust God to use it." },
  { ref: "Isaiah 58:10", text: "and if you give yourself to the hungry and satisfy the afflicted soul, then your light will go forth in the darkness, and your night will be like noonday.", theme: "Caring for the needy", instruction: "When we pour ourselves out for the hungry and afflicted, our light rises in the darkness. Do one practical thing today for someone in need: food, money or your time." },
  { ref: "Isaiah 60:1", text: "Arise, shine, for your light has come, and the glory of the LORD rises upon you.", theme: "Arise and shine", instruction: "Because God's glory has risen on His people, we are to shine. Let your faith be seen today through one act of kindness done openly in Jesus' name." },
  { ref: "Isaiah 61:1", text: "The Spirit of the Lord GOD is on Me, because the LORD has anointed Me to preach good news to the poor. He has sent Me to bind up the brokenhearted, to proclaim liberty to the captives and freedom to the prisoners,", theme: "Good news for the poor", instruction: "Jesus said this passage was fulfilled in Him: good news for the poor and healing for the broken-hearted. Pray for someone you know who is broken-hearted, and send them a message today." },
  { ref: "Jeremiah 17:7-8", text: "But blessed is the man who trusts in the LORD, whose confidence is in Him. He is like a tree planted by the waters that sends out its roots toward the stream. It does not fear when the heat comes, and its leaves are always green. It does not worry in a year of drought, nor does it cease to produce fruit.", theme: "Rooted in trust", instruction: "The person who trusts the Lord is like a tree planted by water, still green in drought. Identify where you are depending on yourself, and pray today to put your trust in God there." },
  { ref: "Jeremiah 29:11", text: "For I know the plans I have for you, declares the LORD, plans to prosper you and not to harm you, to give you a future and a hope.", theme: "God's plans", instruction: "God spoke these words to exiles in Babylon: His plans for them were for good, with a future and a hope. If you feel stuck in a hard place, thank God today that He has not forgotten your future." },
  { ref: "Jeremiah 29:13", text: "You will seek Me and find Me when you search for Me with all your heart.", theme: "Seeking with all your heart", instruction: "God promises to be found by those who seek Him with all their heart. Set aside unhurried time today to seek God, with no distractions and no rush." },
  { ref: "Jeremiah 31:3", text: "The LORD appeared to us in the past, saying: “I have loved you with an everlasting love; therefore I have drawn you with loving devotion.", theme: "Everlasting love", instruction: "God loves His people with an everlasting love, and draws them with kindness. Say aloud today, \"God loves me with an everlasting love,\" whenever you feel unloved." },
  { ref: "Jeremiah 32:17", text: "“Oh, Lord GOD! You have made the heavens and the earth by Your great power and outstretched arm. Nothing is too difficult for You!", theme: "Nothing too hard", instruction: "God made the heavens and earth by His great power, so nothing is too hard for Him. Pray today about one thing you had stopped praying for because it seemed too hard." },
  { ref: "Jeremiah 33:3", text: "Call to Me, and I will answer and show you great and unsearchable things you do not know.", theme: "Call to Me", instruction: "God invites us to call on Him, and He will answer and show us things we do not know. Bring God one question you have about your life today, and listen as you read His Word." },
  { ref: "Lamentations 3:22-23", text: "Because of the loving devotion of the LORD we are not consumed, for His mercies never fail. They are new every morning; great is Your faithfulness!", theme: "New every morning", instruction: "Even after Jerusalem fell, Jeremiah found that God's mercies are new every morning. Tomorrow when you wake, thank God first for His new mercy before you think about problems." },
  { ref: "Ezekiel 36:26", text: "I will give you a new heart and put a new spirit within you; I will remove your heart of stone and give you a heart of flesh.", theme: "A new heart", instruction: "God promises to replace a heart of stone with a heart of flesh: soft and responsive to Him. Name one area where your heart has become hard, and ask God to soften it today." },
  { ref: "Daniel 1:8", text: "But Daniel made up his mind that he would not defile himself with the king’s food or wine. So he asked the chief official for permission not to defile himself.", theme: "Resolve to be faithful", instruction: "Daniel decided in advance that he would not defile himself, even in a foreign king's palace. Decide today, before temptation comes, one specific line you will not cross." },
  { ref: "Daniel 3:17-18", text: "If the God whom we serve exists, then He is able to deliver us from the blazing fiery furnace and from your hand, O king. But even if He does not, let it be known to you, O king, that we will not serve your gods or worship the golden statue you have set up.”", theme: "Faith even if", instruction: "The three friends trusted God to save them, but said they would obey even if He did not. Tell God today that you will follow Him whatever happens in the situation you are praying about." },
  { ref: "Daniel 6:10", text: "Now when Daniel learned that the document had been signed, he went into his house, where the windows of his upper room opened toward Jerusalem, and three times a day he got down on his knees, prayed, and gave thanks to his God, just as he had done before.", theme: "A habit of prayer", instruction: "Daniel kept praying three times a day as he always had, even when it was forbidden. Choose fixed times to pray today, morning, midday and evening, and keep them." },
  { ref: "Hosea 6:3", text: "So let us know — let us press on to know the LORD. As surely as the sun rises, He will appear; He will come to us like the rain, like the spring showers that water the earth.", theme: "Pressing on to know Him", instruction: "Hosea urges God's people to press on to know the Lord. Choose one attribute of God, such as His patience or holiness, and read a passage about it today." },
  { ref: "Joel 2:13", text: "So rend your hearts and not your garments, and return to the LORD your God. For He is gracious and compassionate, slow to anger, abounding in loving devotion. And He relents from sending disaster.", theme: "Return to the Lord", instruction: "God wants a torn heart, real repentance, not torn clothes for show. Turn back to God today in one area where you have drifted, with an honest prayer." },
  { ref: "Amos 5:24", text: "But let justice roll on like a river, and righteousness like an ever-flowing stream.", theme: "Justice and righteousness", instruction: "God wants justice and righteousness to flow constantly like a river, not only religious ceremonies. Treat someone fairly today, especially someone with less power than you." },
  { ref: "Jonah 2:9", text: "But I, with the voice of thanksgiving, will sacrifice to You. I will fulfill what I have vowed. Salvation is from the LORD!”", theme: "Salvation is from the Lord", instruction: "From inside the fish, Jonah declared that salvation comes from the Lord alone. Thank God today for a time He rescued you when you could not rescue yourself." },
  { ref: "Micah 6:8", text: "He has shown you, O man, what is good. And what does the LORD require of you but to act justly, to love mercy, and to walk humbly with your God?", theme: "What the Lord requires", instruction: "God has shown what He requires: to act justly, love mercy and walk humbly with Him. Choose one of the three and practise it deliberately today." },
  { ref: "Micah 7:18", text: "Who is a God like You, who pardons iniquity and passes over the transgression of the remnant of His inheritance — who does not retain His anger forever, because He delights in loving devotion?", theme: "God delights in mercy", instruction: "God does not stay angry forever; He delights to show mercy. If you think God is tired of forgiving you, read this verse aloud and receive His mercy today." },
  { ref: "Nahum 1:7", text: "The LORD is good, a stronghold in the day of distress; He cares for those who trust in Him.", theme: "A stronghold in trouble", instruction: "The Lord is good, a safe place in the day of trouble, and He knows those who trust Him. When trouble comes today, go to God first and tell Him you trust Him." },
  { ref: "Habakkuk 3:17-18", text: "Though the fig tree does not bud and no fruit is on the vines, though the olive crop fails and the fields produce no food, though the sheep are cut off from the fold and no cattle are in the stalls, yet I will exult in the LORD; I will rejoice in the God of my salvation!", theme: "Joy in every season", instruction: "Even with no crops and no animals, Habakkuk chose to rejoice in God Himself. Name one thing that is missing in your life, and choose to praise God for who He is anyway." },
  { ref: "Zephaniah 3:17", text: "The LORD your God is among you; He is mighty to save. He will rejoice over you with gladness; He will quiet you with His love; He will rejoice over you with singing.”", theme: "God rejoices over you", instruction: "God is with His people, mighty to save, and He rejoices over them with singing. Read this verse slowly today and let it change how you think God sees you." },
  { ref: "Haggai 1:5", text: "Now this is what the LORD of Hosts says: “Consider carefully your ways.", theme: "Consider your ways", instruction: "God told the people to think carefully about their ways, because they had put their own houses before His. Look at your week honestly and ask: where did God come in my priorities?" },
  { ref: "Zechariah 4:6", text: "So he said to me, “This is the word of the LORD to Zerubbabel: Not by might nor by power, but by My Spirit, says the LORD of Hosts.", theme: "By My Spirit", instruction: "God's work is done not by human might or power, but by His Spirit. Before a task that is too big for you today, ask the Holy Spirit for His help by name." },
  { ref: "Malachi 3:10", text: "Bring the full tithe into the storehouse, so that there may be food in My house. Test Me in this,” says the LORD of Hosts. “See if I will not open the windows of heaven and pour out for you blessing without measure.", theme: "Faithful giving", instruction: "God invited His people to bring the whole tithe and test His faithfulness. Review your giving this month and decide one faithful step to honour God with your money." },
  { ref: "Matthew 4:4", text: "But Jesus answered, “It is written: ‘Man shall not live on bread alone, but on every word that comes from the mouth of God.’4:4 Deuteronomy 8:3|DEU 8:3”", theme: "Living on God's Word", instruction: "Jesus answered temptation with Scripture: people live by every word from God, not by bread alone. Read God's Word today before you eat breakfast or check your phone." },
  { ref: "Matthew 4:19", text: "“Come, follow Me,” Jesus said, “and I will make you fishers of men.”", theme: "Follow Me", instruction: "Jesus called fishermen to follow Him and promised to make them fishers of people. Pray today for one person who does not yet follow Jesus, by name." },
  { ref: "Matthew 5:3", text: "“Blessed are the poor in spirit, for theirs is the kingdom of heaven.", theme: "Poor in spirit", instruction: "The poor in spirit, those who know they need God, receive the kingdom of heaven. Tell God honestly today one area where you know you cannot manage without Him." },
  { ref: "Matthew 5:9", text: "Blessed are the peacemakers, for they will be called sons of God.", theme: "Peacemakers", instruction: "Peacemakers are called children of God because they share their Father's heart. Help bring peace today in one conflict, at home, work or in your group." },
  { ref: "Matthew 5:14", text: "You are the light of the world. A city on a hill5:14 Literally A city lying on a hill cannot be hidden.", theme: "The light of the world", instruction: "Jesus' followers are the light of the world, meant to be seen, not hidden. Let your faith be visible today in one way: a prayer, a kind act or speaking about Jesus." },
  { ref: "Matthew 5:16", text: "In the same way, let your light shine before men, that they may see your good deeds and glorify your Father in heaven.", theme: "Let your light shine", instruction: "Our good works should be seen so that people give glory to our Father in heaven, not to us. Do one good deed today and, if asked, give God the credit." },
  { ref: "Matthew 5:44", text: "But I tell you, love your enemies and pray for those who persecute you,", theme: "Love your enemies", instruction: "Jesus tells us to love our enemies and pray for those who persecute us. Pray for someone who has hurt you today, by name, asking God to bless them." },
  { ref: "Matthew 6:6", text: "But when you pray, go into your inner room, shut your door, and pray to your Father, who is unseen. And your Father, who sees what is done in secret, will reward you.", theme: "Praying in secret", instruction: "Jesus teaches us to pray in private, where only the Father sees. Find a private place today, close the door, and pray for ten minutes." },
  { ref: "Matthew 6:9-10", text: "So then, this is how you should pray: ‘Our Father in heaven, hallowed be Your name. Your kingdom come, Your will be done, on earth as it is in heaven.", theme: "The Lord's Prayer", instruction: "Jesus taught His disciples to pray first for God's name, kingdom and will. Pray the Lord's Prayer slowly today, stopping after each line to apply it to your life." },
  { ref: "Matthew 6:14", text: "For if you forgive men their trespasses, your heavenly Father will also forgive you.", theme: "Forgiving others", instruction: "Jesus links our forgiveness from God with our forgiving others. Name one person you have not forgiven, and pray today: \"Father, I choose to forgive them.\"" },
  { ref: "Matthew 6:21", text: "For where your treasure is, there your heart will be also.", theme: "Where your treasure is", instruction: "Where our treasure is, there our heart will be. Look at your spending this week and ask what it shows about your heart." },
  { ref: "Matthew 6:33", text: "But seek first the kingdom of God and His righteousness, and all these things will be added unto you.", theme: "Seek first the Kingdom", instruction: "Jesus tells us to seek God's kingdom first, and He will provide what we need. Put God first today by praying and reading before you begin work." },
  { ref: "Matthew 6:34", text: "Therefore do not worry about tomorrow, for tomorrow will worry about itself. Today has enough trouble of its own.", theme: "One day at a time", instruction: "Jesus tells us not to worry about tomorrow; each day has enough trouble of its own. Write down what you are worried about for tomorrow, pray over it, and focus on today's tasks." },
  { ref: "Matthew 7:7", text: "Ask, and it will be given to you; seek, and you will find; knock, and the door will be opened to you.", theme: "Ask, seek, knock", instruction: "Jesus invites us to keep asking, seeking and knocking. Choose one request you have stopped praying about and start praying it again today." },
  { ref: "Matthew 7:12", text: "In everything, then, do to others as you would have them do to you. For this is the essence of the Law and the Prophets.", theme: "The golden rule", instruction: "Jesus summarises the Law: treat others the way you want them to treat you. Before you reply to someone today, ask: \"How would I want to be treated here?\"" },
  { ref: "Matthew 7:24", text: "Therefore everyone who hears these words of Mine and acts on them is like a wise man who built his house on the rock.", theme: "Building on the rock", instruction: "The wise builder hears Jesus' words and puts them into practice. Choose one teaching of Jesus you already know and obey it today." },
  { ref: "Matthew 9:37-38", text: "Then He said to His disciples, “The harvest is plentiful, but the workers are few. Ask the Lord of the harvest, therefore, to send out workers into His harvest.”", theme: "Workers for the harvest", instruction: "The harvest is plentiful but the workers are few, so Jesus tells us to pray for workers. Pray today for more people to share the gospel, and offer yourself as one of them." },
  { ref: "Matthew 10:8", text: "Heal the sick, raise the dead, cleanse the lepers, drive out demons. Freely you have received; freely give.", theme: "Freely give", instruction: "Jesus sent His disciples out saying: you received freely, so give freely. Think of one thing God gave you without charge, and give something to someone today without expecting anything back." },
  { ref: "Matthew 11:28", text: "Come to Me, all you who are weary and burdened, and I will give you rest.", theme: "Rest for the weary", instruction: "Jesus invites everyone who is tired and burdened to come to Him for rest. Tell Jesus specifically what is wearing you out today, and leave it with Him in prayer." },
  { ref: "Matthew 11:29", text: "Take My yoke upon you and learn from Me, for I am gentle and humble in heart, and you will find rest for your souls.", theme: "Learning from Jesus", instruction: "Jesus is gentle and humble in heart, and learning from Him brings rest to our souls. Read one passage about how Jesus treated people today, and copy His gentleness in one conversation." },
  { ref: "Matthew 16:24", text: "Then Jesus told His disciples, “If anyone wants to come after Me, he must deny himself and take up his cross and follow Me.", theme: "Taking up the cross", instruction: "Following Jesus means denying ourselves and taking up our cross. Name one thing you want that Jesus would not choose, and say no to it today." },
  { ref: "Matthew 18:20", text: "For where two or three gather together in My name, there am I with them.”", theme: "Gathered in His name", instruction: "Jesus is present where two or three gather in His name. Pray with at least one other believer today, in person or by phone." },
  { ref: "Matthew 18:21-22", text: "Then Peter came to Jesus and asked, “Lord, how many times shall I forgive my brother who sins against me? Up to seven times?” Jesus answered, “I tell you, not just seven times, but seventy-seven times!", theme: "Forgiving again", instruction: "Jesus told Peter to forgive not seven times but seventy-seven times: without keeping count. If someone keeps hurting you, forgive them again today, and ask God for wisdom about the relationship." },
  { ref: "Matthew 19:26", text: "Jesus looked at them and said, “With man this is impossible, but with God all things are possible.”", theme: "All things possible", instruction: "With people some things are impossible, but with God all things are possible. Pray today about the one situation you had given up on." },
  { ref: "Matthew 22:37-39", text: "Jesus declared, “‘Love the Lord your God with all your heart and with all your soul and with all your mind.’22:37 Deuteronomy 6:5|DEU 6:5 This is the first and greatest commandment. And the second is like it: ‘Love your neighbor as yourself.’", theme: "The greatest commandments", instruction: "The greatest commandments are to love God with everything, and to love your neighbour as yourself. Do one thing today to show love to God and one thing to show love to a neighbour." },
  { ref: "Matthew 25:40", text: "And the King will reply, ‘Truly I tell you, whatever you did for one of the least of these brothers of Mine, you did for Me.’", theme: "Serving the least", instruction: "What we do for the least of Jesus' brothers and sisters, we do for Him. Serve someone today who cannot repay you, and remember you are serving Jesus." },
  { ref: "Matthew 28:20", text: "and teaching them to obey all that I have commanded you. And surely I am with you always, even to the end of the age.”", theme: "He is with us always", instruction: "Jesus promised to be with His disciples always, to the end of the age. When you feel alone today, say: \"Jesus, You are with me right now.\"" },
  { ref: "Mark 1:35", text: "Early in the morning, while it was still dark, Jesus got up and went out to a solitary place to pray.", theme: "Early prayer", instruction: "Before a busy day, Jesus went out early to a quiet place to pray. Get up ten minutes earlier tomorrow and pray before anything else." },
  { ref: "Mark 8:36", text: "What does it profit a man to gain the whole world, yet forfeit his soul?", theme: "What truly matters", instruction: "Gaining the whole world is worthless if we lose our soul. Look at what you are chasing most this year, and ask God if it is worth your soul." },
  { ref: "Mark 9:24", text: "Immediately the boy’s father cried out, “I do believe; help my unbelief!”", theme: "Help my unbelief", instruction: "A desperate father prayed, \"I believe; help my unbelief,\" and Jesus answered him. Bring your doubts to God honestly today with this same prayer." },
  { ref: "Mark 10:45", text: "For even the Son of Man did not come to be served, but to serve, and to give His life as a ransom for many.”", theme: "Came to serve", instruction: "Jesus came not to be served but to serve and give His life. Serve someone today in a way that costs you, without being asked." },
  { ref: "Mark 11:24", text: "Therefore I tell you, whatever you ask for in prayer, believe that you have received it, and it will be yours.", theme: "Praying in faith", instruction: "Jesus teaches us to pray believing that God hears and will answer. Pray for one specific need today, and thank God in advance for hearing you." },
  { ref: "Mark 12:30", text: "Love the Lord your God with all your heart and with all your soul and with all your mind and with all your strength.’", theme: "Loving God fully", instruction: "We are to love God with all our mind as well as our heart. Spend time today studying a passage carefully, asking what it teaches about God." },
  { ref: "Mark 16:15", text: "And He said to them, “Go into all the world and preach the gospel to every creature.", theme: "Go into all the world", instruction: "Jesus sent His followers into all the world to preach the gospel to everyone. Pray today for one unreached people group, and share Jesus with one person you meet." },
  { ref: "Luke 1:37", text: "For no word from God will ever fail.”", theme: "Nothing impossible with God", instruction: "The angel told Mary that no word from God will fail. Pray today about one thing God has promised that seems impossible to you." },
  { ref: "Luke 1:38", text: "“I am the Lord’s servant,” Mary answered. “May it happen to me according to your word.” Then the angel left her.", theme: "Willing obedience", instruction: "Mary answered, \"I am the Lord's servant; may it be to me as you have said.\" Tell God today you are willing to do what He asks, and name one thing He has been asking." },
  { ref: "Luke 2:10-11", text: "But the angel said to them, “Do not be afraid! For behold, I bring you good news of great joy that will be for all the people: Today in the city of David a Savior has been born to you. He is Christ the Lord!", theme: "Good news of great joy", instruction: "The angels announced good news of great joy for all people: a Saviour is born. Tell one person today, in your own words, why Jesus is good news for you." },
  { ref: "Luke 5:16", text: "Yet He frequently withdrew to the wilderness to pray.", theme: "Withdrawing to pray", instruction: "Even as crowds grew, Jesus often withdrew to lonely places to pray. Step away from busyness today for fifteen minutes alone with God." },
  { ref: "Luke 6:31", text: "Do to others as you would have them do to you.", theme: "Treating others well", instruction: "Treat others the way you want to be treated. Think of how you want to be spoken to, and speak to everyone that way today." },
  { ref: "Luke 6:38", text: "Give, and it will be given to you. A good measure, pressed down, shaken together, and running over will be poured into your lap. For with the measure you use, it will be measured back to you.”", theme: "Give and it will be given", instruction: "Jesus promised that the measure we give with is the measure we receive. Give generously today, of money, time or forgiveness, and trust God with the rest." },
  { ref: "Luke 9:23", text: "Then Jesus said to all of them, “If anyone wants to come after Me, he must deny himself and take up his cross daily and follow Me.", theme: "Daily discipleship", instruction: "Following Jesus is a daily choice to deny ourselves and take up our cross. Ask Jesus this morning, \"What does following You look like today?\" and do it." },
  { ref: "Luke 10:27", text: "He answered, “‘Love the Lord your God with all your heart and with all your soul and with all your strength and with all your mind’ and ‘Love your neighbor as yourself.’”", theme: "Love God and neighbour", instruction: "Loving God and loving our neighbour go together. Show love today to someone near you whom you usually ignore." },
  { ref: "Luke 10:41-42", text: "“Martha, Martha,” the Lord replied, “you are worried and upset about many things. But only one thing is necessary. Mary has chosen the good portion, and it will not be taken away from her.”", theme: "The one thing needed", instruction: "Martha was busy serving, but Mary sat at Jesus' feet, and Jesus said Mary chose the better part. Before your work today, sit for ten minutes with Jesus in His Word." },
  { ref: "Luke 11:1", text: "One day in a place where Jesus had just finished praying, one of His disciples requested, “Lord, teach us to pray, just as John taught his disciples.”", theme: "Teach us to pray", instruction: "The disciples asked Jesus to teach them to pray, and He gave them the Lord's Prayer. Ask Jesus today to teach you to pray, and pray through Luke 11:2-4." },
  { ref: "Luke 12:15", text: "And He said to them, “Watch out! Guard yourselves against every form of greed, for one’s life does not consist in the abundance of his possessions.”", theme: "Guarding against greed", instruction: "Jesus warned that life does not consist in the abundance of possessions. Give away one thing today that you do not need." },
  { ref: "Luke 15:7", text: "I tell you that in the same way there will be more joy in heaven over one sinner who repents than over ninety-nine righteous ones who do not need to repent.", theme: "Joy in heaven", instruction: "There is more joy in heaven over one sinner who repents. Pray today for one person who does not know Jesus, and look for a chance to talk with them." },
  { ref: "Luke 15:20", text: "So he got up and went to his father. But while he was still in the distance, his father saw him and was filled with compassion. He ran to his son, embraced him, and kissed him.", theme: "The Father's welcome", instruction: "The father ran to welcome his returning son before he could finish his apology. If you have drifted from God, come back to Him in prayer today, knowing He runs to welcome you." },
  { ref: "Luke 18:1", text: "Then Jesus told them a parable about their need to pray at all times and not lose heart:", theme: "Keep praying", instruction: "Jesus told a parable so that His disciples would always pray and not give up. Keep praying today about the request you are tempted to abandon." },
  { ref: "Luke 19:10", text: "For the Son of Man came to seek and to save the lost.”", theme: "Seeking the lost", instruction: "Jesus came to seek and to save the lost, like Zacchaeus. Ask God to show you one person who is far from Him, and reach out to them this week." },
  { ref: "Luke 24:32", text: "They asked each other, “Were not our hearts burning within us as He spoke with us on the road and opened the Scriptures to us?”", theme: "Hearts burning", instruction: "The disciples' hearts burned as Jesus explained the Scriptures to them on the road. Read a passage about Jesus today and ask Him to open its meaning to you." },
  { ref: "John 1:1", text: "In the beginning was the Word, and the Word was with God, and the Word was God.", theme: "The Word", instruction: "Before creation, the Word already existed, was with God, and was God: Jesus. Read John 1:1-14 today and thank Jesus that He became human to make God known." },
  { ref: "John 1:12", text: "But to all who did receive Him, to those who believed in His name, He gave the right to become children of God —", theme: "Children of God", instruction: "Everyone who receives Jesus and believes in His name is given the right to become God's child. Thank God today that you are His child, not just His servant." },
  { ref: "John 3:16", text: "For God so loved the world that He gave His one and only3:16 Or only begotten or unique; also in verse 18 Son, that everyone who believes in Him shall not perish but have eternal life.", theme: "God's love for the world", instruction: "God loved the world so much that He gave His only Son, so that whoever believes would not perish. Tell one person today, in your own words, how much God loves them." },
  { ref: "John 3:30", text: "He must increase; I must decrease.", theme: "He must increase", instruction: "John the Baptist said Jesus must become greater while he became less. Look for one moment today to point attention to Jesus rather than to yourself." },
  { ref: "John 4:24", text: "God is Spirit, and His worshipers must worship Him in spirit and in truth.”", theme: "Worship in spirit and truth", instruction: "God is Spirit, and He wants worship that is real and true, not just outward. Worship God today with honest words from your heart, not only familiar phrases." },
  { ref: "John 6:35", text: "Jesus answered, “I am the bread of life. Whoever comes to Me will never hunger, and whoever believes in Me will never thirst.", theme: "The bread of life", instruction: "Jesus is the bread of life; whoever comes to Him will never go hungry. Bring the empty place in your life to Jesus today and ask Him to fill it." },
  { ref: "John 8:12", text: "Once again, Jesus spoke to the people and said, “I am the light of the world. Whoever follows Me will never walk in the darkness, but will have the light of life.”", theme: "The light of the world", instruction: "Jesus is the light of the world; whoever follows Him will not walk in darkness. In the area of life where you feel confused, ask Jesus to show you His light today." },
  { ref: "John 8:32", text: "Then you will know the truth, and the truth will set you free.”", theme: "The truth sets free", instruction: "The truth Jesus teaches sets people free. Name one lie you have believed about yourself or God, and find a verse that tells the truth instead." },
  { ref: "John 10:10", text: "The thief comes only to steal and kill and destroy. I have come that they may have life, and have it in all its fullness.", theme: "Abundant life", instruction: "The thief comes to steal and destroy, but Jesus came to give life in its fullness. Thank Jesus today for one area where He has brought new life to you." },
  { ref: "John 10:11", text: "I am the good shepherd. The good shepherd lays down His life for the sheep.", theme: "The good shepherd", instruction: "Jesus is the good shepherd who lays down His life for the sheep. Read John 10:1-18 today and thank Jesus that He gave His life for you." },
  { ref: "John 10:27", text: "My sheep listen to My voice; I know them, and they follow Me.", theme: "Knowing His voice", instruction: "Jesus' sheep hear His voice, He knows them, and they follow Him. Spend quiet time in the Gospels today and ask Jesus to help you recognise His voice." },
  { ref: "John 11:25", text: "Jesus said to her, “I am the resurrection and the life. Whoever believes in Me will live, even though he dies.", theme: "The resurrection and the life", instruction: "Jesus is the resurrection and the life; whoever believes in Him will live even though they die. If you are grieving, read John 11 today and hold on to this promise." },
  { ref: "John 13:34-35", text: "A new commandment I give you: Love one another. As I have loved you, so you also must love one another. By this everyone will know that you are My disciples, if you love one another.”", theme: "Love one another", instruction: "People will know we are Jesus' disciples by our love for one another. Show love today to another believer in a way others can notice." },
  { ref: "John 14:1", text: "“Do not let your hearts be troubled. You believe in God; believe in Me as well.", theme: "Do not be troubled", instruction: "Jesus told His disciples not to let their hearts be troubled, but to trust God and trust Him. Name what troubles you most today and tell Jesus you trust Him with it." },
  { ref: "John 14:6", text: "Jesus answered, “I am the way and the truth and the life. No one comes to the Father except through Me.", theme: "The way, the truth, the life", instruction: "Jesus is the way, the truth and the life; no one comes to the Father except through Him. Thank Jesus today that through Him you can come to the Father." },
  { ref: "John 14:15", text: "If you love Me, you will keep14:15 Or If you love Me, keep My commandments.", theme: "Love and obedience", instruction: "Jesus said that those who love Him will keep His commandments. Choose one command of Jesus you have been neglecting and obey it today." },
  { ref: "John 14:27", text: "Peace I leave with you; My peace I give to you. I do not give to you as the world gives. Do not let your hearts be troubled; do not be afraid.", theme: "His peace", instruction: "Jesus gives a peace that is different from the world's peace, one that stays in trouble. When worry comes today, pray: \"Jesus, I receive Your peace.\"" },
  { ref: "John 15:12", text: "This is My commandment, that you love one another as I have loved you.", theme: "Love as He loved", instruction: "Jesus commands us to love one another as He has loved us: sacrificially. Love someone today in a way that costs you time, comfort or pride." },
  { ref: "John 15:13", text: "Greater love has no one than this, that he lay down his life for his friends.", theme: "Laying down your life", instruction: "The greatest love is to lay down one's life for one's friends. Give up something of your own today for a friend's good." },
  { ref: "John 16:33", text: "I have told you these things so that in Me you may have peace. In the world you will have tribulation. But take courage; I have overcome the world!”", theme: "He has overcome", instruction: "Jesus said we will have trouble in this world, but He has overcome the world. In today's trouble, pray: \"Jesus, You have overcome this too.\"" },
  { ref: "John 17:17", text: "Sanctify them by the truth; Your word is truth.", theme: "Sanctified by the truth", instruction: "Jesus prayed that His followers would be made holy by the truth of God's Word. Read Scripture today and ask God to change one attitude in you through it." },
  { ref: "John 20:21", text: "Again Jesus said to them, “Peace be with you. As the Father has sent Me, so also I am sending you.”", theme: "Sent as He was sent", instruction: "Jesus sends His disciples just as the Father sent Him. Ask Jesus today where He is sending you, at work, school or home, and go as His representative." },
  { ref: "John 21:17", text: "Jesus asked a third time, “Simon son of John, do you love Me?” Peter was deeply hurt that Jesus had asked him a third time, “Do you love Me?” “Lord, You know all things,” he replied. “You know I love You.” Jesus said to him, “Feed My sheep.", theme: "Feed My sheep", instruction: "Jesus restored Peter and gave him a task: \"Feed My sheep.\" Encourage or teach someone in your group today, as a way of loving Jesus." },
  { ref: "Acts 1:8", text: "But you will receive power when the Holy Spirit comes upon you, and you will be My witnesses in Jerusalem, and in all Judea and Samaria, and to the ends of the earth.”", theme: "Witnesses", instruction: "The Holy Spirit gives power to be Jesus' witnesses, starting at home and going to the whole world. Ask the Holy Spirit for courage today, and tell one person what Jesus means to you." },
  { ref: "Acts 4:12", text: "Salvation exists in no one else, for there is no other name under heaven given to men by which we must be saved.”", theme: "Salvation in Jesus alone", instruction: "There is salvation in no one else but Jesus. Thank Jesus today for saving you, and pray for someone who is looking for salvation elsewhere." },
  { ref: "Acts 4:31", text: "After they had prayed, their meeting place was shaken, and they were all filled with the Holy Spirit and spoke the word of God boldly.", theme: "Boldness", instruction: "When the believers prayed, they were filled with the Holy Spirit and spoke God's word boldly. Pray today for boldness to speak about Jesus, and take one opportunity." },
  { ref: "Acts 16:25", text: "About midnight Paul and Silas were praying and singing hymns to God, and the other prisoners were listening to them.", theme: "Praise in hard places", instruction: "In prison, beaten and chained, Paul and Silas prayed and sang hymns at midnight. In the hardest part of your day, stop and praise God aloud." },
  { ref: "Acts 17:11", text: "Now the Bereans were more noble-minded than the Thessalonians, for they received the message with great eagerness and examined the Scriptures every day to see if these teachings were true.", theme: "Examining the Scriptures", instruction: "The Bereans received the word eagerly and checked the Scriptures daily to see if it was true. Check one teaching you heard recently against what the Bible actually says." },
  { ref: "Acts 20:24", text: "But I consider my life of no value to me, if only I may finish my course and complete the ministry I have received from the Lord Jesus — the ministry of testifying to the good news of God’s grace.", theme: "Finishing the race", instruction: "Paul considered his life worth nothing except finishing the task Jesus gave him. Ask God what task He has given you, and do one part of it today." },
  { ref: "Acts 20:35", text: "In everything, I showed you that by this kind of hard work we must help the weak, remembering the words of the Lord Jesus Himself: ‘It is more blessed to give than to receive.’”", theme: "More blessed to give", instruction: "Jesus said it is more blessed to give than to receive. Give something today to someone who cannot repay you." },
  { ref: "Romans 1:16", text: "I am not ashamed of the gospel, because it is the power of God for salvation to everyone who believes, first to the Jew, then to the Greek.", theme: "Not ashamed", instruction: "Paul was not ashamed of the gospel, because it is God's power to save everyone who believes. Share the gospel or your testimony with one person today without apologising for it." },
  { ref: "Romans 3:23-24", text: "for all have sinned and fall short of the glory of God, and are justified freely by His grace through the redemption that is in Christ Jesus.", theme: "Grace for all", instruction: "All have sinned and fall short, but all can be justified freely by God's grace through Jesus. Thank God today that you are made right with Him as a gift, not as a reward." },
  { ref: "Romans 5:1", text: "Therefore, since we have been justified through faith, we have peace with God through our Lord Jesus Christ,", theme: "Peace with God", instruction: "Being justified by faith, we have peace with God through Jesus. If you feel distant from God, thank Him today that the war is over and you are at peace with Him." },
  { ref: "Romans 5:8", text: "But God proves His love for us in this: While we were still sinners, Christ died for us.", theme: "God's love shown", instruction: "God showed His love by Christ dying for us while we were still sinners, before we changed. Thank God today that His love did not wait for you to be good." },
  { ref: "Romans 6:23", text: "For the wages of sin is death, but the gift of God is eternal life in Christ Jesus our Lord.", theme: "The gift of God", instruction: "Sin earns death, but God gives eternal life as a free gift in Christ. Thank God today for this gift, and explain it to someone in simple words." },
  { ref: "Romans 8:1", text: "Therefore, there is now no condemnation for those who are in Christ Jesus.", theme: "No condemnation", instruction: "There is no condemnation for those who are in Christ Jesus. If the accuser reminds you of confessed sin today, answer with this verse." },
  { ref: "Romans 8:28", text: "And we know that God works all things together for the good of those who love Him, who are called according to His purpose.", theme: "God works for good", instruction: "God works all things together for good for those who love Him. Name one hard thing in your life and ask God to work good through it." },
  { ref: "Romans 8:31", text: "What then shall we say in response to these things? If God is for us, who can be against us?", theme: "God is for us", instruction: "If God is for us, no opposition can ultimately stand against us. Face today's opposition by praying this verse aloud first." },
  { ref: "Romans 8:38-39", text: "For I am convinced that neither death nor life, neither angels nor principalities, neither the present nor the future, nor any powers, neither height nor depth, nor anything else in all creation, will be able to separate us from the love of God that is in Christ Jesus our Lord.", theme: "Nothing can separate us", instruction: "Nothing in all creation can separate us from God's love in Christ. Read these verses aloud today, naming your fears in place of the list." },
  { ref: "Romans 10:9", text: "that if you confess with your mouth, “Jesus is Lord,” and believe in your heart that God raised Him from the dead, you will be saved.", theme: "Confessing Jesus as Lord", instruction: "Whoever confesses Jesus as Lord and believes God raised Him from the dead will be saved. Say today, out loud, \"Jesus is Lord,\" and let it decide one choice you make." },
  { ref: "Romans 10:17", text: "Consequently, faith comes by hearing, and hearing by the word of Christ.", theme: "Faith from hearing", instruction: "Faith comes from hearing the message about Christ. Listen to a chapter of the Bible read aloud today." },
  { ref: "Romans 12:1", text: "Therefore I urge you, brothers, on account of God’s mercy, to offer your bodies as living sacrifices, holy and pleasing to God, which is your spiritual service of worship.", theme: "A living sacrifice", instruction: "Because of God's mercy, we offer our whole bodies to Him as a living sacrifice. Offer your body to God this morning: your eyes, hands, tongue and feet for today." },
  { ref: "Romans 12:2", text: "Do not be conformed to this world, but be transformed by the renewing of your mind. Then you will be able to test and approve what is the good, pleasing, and perfect will of God.", theme: "Renewing the mind", instruction: "We are transformed by the renewing of our minds, not by copying the world's pattern. Name one way you think like the world, and find a verse that renews that thought." },
  { ref: "Romans 12:10", text: "Be devoted to one another in brotherly love. Outdo yourselves in honoring one another.", theme: "Honouring one another", instruction: "We are to love one another deeply and outdo each other in showing honour. Honour someone today by putting their needs or opinion before your own." },
  { ref: "Romans 12:12", text: "Be joyful in hope, patient in affliction, persistent in prayer.", theme: "Joyful, patient, faithful", instruction: "Be joyful in hope, patient in trouble and faithful in prayer. Pick the one of the three you find hardest and practise it today." },
  { ref: "Romans 12:18", text: "If it is possible on your part, live at peace with everyone.", theme: "Living at peace", instruction: "As far as it depends on you, live at peace with everyone. Take one step toward peace today with someone you are in conflict with." },
  { ref: "Romans 12:21", text: "Do not be overcome by evil, but overcome evil with good.", theme: "Overcoming evil with good", instruction: "Do not be overcome by evil, but overcome evil with good. When someone is unkind to you today, answer with a kindness." },
  { ref: "Romans 15:13", text: "Now may the God of hope fill you with all joy and peace as you believe in Him, so that you may overflow with hope by the power of the Holy Spirit.", theme: "The God of hope", instruction: "The God of hope fills us with joy and peace as we trust Him. Ask God today to fill you with hope by His Spirit, and name one thing you are hoping in Him for." },
  { ref: "1 Corinthians 2:9", text: "Rather, as it is written: “No eye has seen, no ear has heard, no heart has imagined, what God has prepared for those who love Him.”", theme: "What God has prepared", instruction: "No eye has seen what God has prepared for those who love Him. Thank God today for good things ahead that you cannot yet see." },
  { ref: "1 Corinthians 10:13", text: "No temptation has seized you except what is common to man. And God is faithful; He will not let you be tempted beyond what you can bear. But when you are tempted, He will also provide an escape, so that you can stand up under it.", theme: "A way out", instruction: "No temptation is beyond what others have faced, and God always provides a way of escape. Identify your common temptation and plan your way out before it comes today." },
  { ref: "1 Corinthians 10:31", text: "So whether you eat or drink or whatever you do, do it all to the glory of God.", theme: "For the glory of God", instruction: "Whether we eat, drink or do anything, we can do it all for God's glory. Choose one ordinary task today and do it consciously for God." },
  { ref: "1 Corinthians 13:4-5", text: "Love is patient, love is kind. It does not envy, it does not boast, it is not proud. It is not rude, it is not self-seeking, it is not easily angered, it keeps no account of wrongs.", theme: "Love is patient", instruction: "Love is patient and kind; it does not envy, boast or keep a record of wrongs. Read these verses, put your name in place of \"love\", and work on the line that is least true of you." },
  { ref: "1 Corinthians 13:13", text: "And now these three remain: faith, hope, and love; but the greatest of these is love.", theme: "The greatest is love", instruction: "Faith, hope and love remain, and the greatest of these is love. Let love decide one choice you make today." },
  { ref: "1 Corinthians 15:58", text: "Therefore, my beloved brothers, be steadfast and immovable. Always excel in the work of the Lord, because you know that your labor in the Lord is not in vain.", theme: "Steadfast work", instruction: "Because of the resurrection, our work for the Lord is never wasted. Keep going today in one task for God that feels unrewarded." },
  { ref: "1 Corinthians 16:14", text: "Do everything in love.", theme: "Do everything in love", instruction: "Do everything in love. Before each conversation today, pause and decide to speak in love." },
  { ref: "2 Corinthians 1:3-4", text: "Blessed be the God and Father of our Lord Jesus Christ, the Father of compassion and the God of all comfort, who comforts us in all our troubles, so that we can comfort those in any trouble with the comfort we ourselves have received from God.", theme: "Comfort to share", instruction: "God comforts us in our troubles so that we can comfort others with the same comfort. Think of a hard time God brought you through, and comfort someone facing the same thing today." },
  { ref: "2 Corinthians 4:16", text: "Therefore we do not lose heart. Though our outer self is wasting away, yet our inner self is being renewed day by day.", theme: "Renewed day by day", instruction: "Paul says our outer self, our body, wears out with age and hardship, but our inner self, our spirit made alive in Christ, is renewed by God every day. Today, give your inner self what renews it: read this chapter, pray honestly about what is wearing you down, and thank God for one way He is growing you inside." },
  { ref: "2 Corinthians 4:18", text: "So we fix our eyes not on what is seen, but on what is unseen. For what is seen is temporary, but what is unseen is eternal.", theme: "What is unseen", instruction: "Paul fixed his eyes on what is unseen and eternal rather than on passing troubles. Spend some of today on something eternal: prayer, God's Word or helping someone know Jesus." },
  { ref: "2 Corinthians 5:7", text: "For we walk by faith, not by sight.", theme: "Walking by faith", instruction: "We live by faith in God, not by what we can see. Take one step today that only makes sense if God is real and faithful." },
  { ref: "2 Corinthians 5:17", text: "Therefore if anyone is in Christ, he is a new creation. The old has passed away. Behold, the new has come!", theme: "A new creation", instruction: "Anyone in Christ is a new creation; the old has gone and the new has come. Name one old habit that no longer fits who you are in Christ, and refuse it today." },
  { ref: "2 Corinthians 5:20", text: "Therefore we are ambassadors for Christ, as though God were making His appeal through us. We implore you on behalf of Christ: Be reconciled to God.", theme: "Ambassadors for Christ", instruction: "We are Christ's ambassadors, as though God were appealing through us. Represent Jesus well today in how you speak to one difficult person." },
  { ref: "2 Corinthians 9:7", text: "Each one should give what he has decided in his heart to give, not out of regret or compulsion. For God loves a cheerful giver.", theme: "A cheerful giver", instruction: "God loves a cheerful giver who gives willingly, not reluctantly or under pressure. Decide in your heart what to give this week, and give it gladly." },
  { ref: "2 Corinthians 12:9", text: "But He said to me, “My grace is sufficient for you, for My power is perfected in weakness.” Therefore I will boast all the more gladly in my weaknesses, so that the power of Christ may rest on me.", theme: "Grace in weakness", instruction: "God told Paul that His grace is enough and His power is made perfect in weakness. Name one weakness you hide, and ask God to show His strength through it today." },
  { ref: "Galatians 2:20", text: "I have been crucified with Christ, and I no longer live, but Christ lives in me. The life I live in the body, I live by faith in the Son of God, who loved me and gave Himself up for me.", theme: "Christ lives in me", instruction: "Paul says he was crucified with Christ, and now Christ lives in him. Live today aware that Christ lives in you, and ask how He would act in one situation." },
  { ref: "Galatians 5:1", text: "It is for freedom that Christ has set us free. Stand firm, then, and do not be encumbered once more by a yoke of slavery.", theme: "Freedom in Christ", instruction: "Christ set us free, so we must not go back to slavery. Name one rule, fear or habit that enslaves you, and stand in Christ's freedom from it today." },
  { ref: "Galatians 5:13", text: "For you, brothers, were called to freedom; but do not use your freedom as an opportunity for the flesh. Rather, serve one another in love.", theme: "Serving in love", instruction: "We are free, but we use our freedom to serve one another in love. Serve someone today with something you have freedom to spend: time, skill or money." },
  { ref: "Galatians 5:22-23", text: "But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. Against such things there is no law.", theme: "Fruit of the Spirit", instruction: "The Spirit produces love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and self-control. Choose the fruit you most lack and ask the Spirit to grow it in you today." },
  { ref: "Galatians 6:2", text: "Carry one another’s burdens, and in this way you will fulfill the law of Christ.", theme: "Carrying burdens", instruction: "Carrying one another's burdens fulfils the law of Christ. Ask someone in your group today what is weighing on them, and help carry it." },
  { ref: "Galatians 6:9", text: "Let us not grow weary in well-doing, for in due time we will reap a harvest if we do not give up.", theme: "Do not grow weary", instruction: "We should not grow tired of doing good, because the harvest will come in time. Keep doing one good thing today that you are tired of doing." },
  { ref: "Ephesians 2:8-9", text: "For it is by grace you have been saved through faith, and this not from yourselves; it is the gift of God, not by works, so that no one can boast.", theme: "Saved by grace", instruction: "We are saved by grace through faith, as a gift from God, not by our works. Thank God today that you cannot earn His love and do not need to." },
  { ref: "Ephesians 2:10", text: "For we are God’s workmanship, created in Christ Jesus to do good works, which God prepared in advance as our way of life.", theme: "Created for good works", instruction: "We are God's workmanship, created in Christ for good works He prepared in advance. Ask God this morning to show you the good work He has prepared for you today." },
  { ref: "Ephesians 3:20", text: "Now to Him who is able to do immeasurably more than all we ask or imagine, according to His power that is at work within us,", theme: "More than we ask", instruction: "God can do far more than all we ask or imagine, by His power at work in us. Pray today for something bigger than you would usually dare ask." },
  { ref: "Ephesians 4:2-3", text: "with all humility and gentleness, with patience, bearing with one another in love, and with diligence to preserve the unity of the Spirit through the bond of peace.", theme: "Keeping unity", instruction: "We keep the unity of the Spirit by being humble, gentle and patient with each other. Be patient today with one believer who frustrates you." },
  { ref: "Ephesians 4:29", text: "Let no unwholesome talk come out of your mouths, but only what is helpful for building up the one in need and bringing grace to those who listen.", theme: "Words that build up", instruction: "Only words that build others up and give grace should come from our mouths. Before you speak today, ask: will this build them up?" },
  { ref: "Ephesians 4:32", text: "Be kind and tenderhearted to one another, forgiving each other just as in Christ God forgave you.", theme: "Kindness and forgiveness", instruction: "Be kind and forgiving, just as God forgave you in Christ. Remember how much God forgave you, and forgive someone today because of it." },
  { ref: "Ephesians 5:15-16", text: "Pay careful attention, then, to how you walk, not as unwise but as wise, redeeming the time, because the days are evil.", theme: "Using time wisely", instruction: "We are to live wisely and make the most of every opportunity. Plan one specific use of your free time today that honours God." },
  { ref: "Ephesians 6:10", text: "Finally, be strong in the Lord and in His mighty power.", theme: "Strong in the Lord", instruction: "Be strong in the Lord and in His mighty power, not in your own. Before a hard task today, pray: \"Lord, I am relying on Your strength.\"" },
  { ref: "Ephesians 6:18", text: "Pray in the Spirit at all times, with every kind of prayer and petition. To this end, stay alert with all perseverance in your prayers for all the saints.", theme: "Praying at all times", instruction: "Paul urges us to pray at all times in the Spirit, for all believers. Pray today for three believers by name and for their specific needs." },
  { ref: "Philippians 1:6", text: "being confident of this, that He who began a good work in you will carry it on to completion until the day of Christ Jesus.", theme: "He will finish His work", instruction: "God, who began a good work in you, will carry it on to completion. Thank God today that He is not finished with you yet." },
  { ref: "Philippians 1:21", text: "For to me, to live is Christ, and to die is gain.", theme: "To live is Christ", instruction: "For Paul, to live was Christ, and to die was gain. Ask yourself what you are living for, and give that to Christ today." },
  { ref: "Philippians 2:3-4", text: "Do nothing out of selfish ambition or empty pride, but in humility consider others more important than yourselves. Each of you should look not only to your own interests, but also to the interests of others.", theme: "Humility", instruction: "Do nothing from selfish ambition; value others above yourself and look to their interests. Look after someone else's interest today before your own." },
  { ref: "Philippians 2:5", text: "Let this mind be in you which was also in Christ Jesus:", theme: "The mind of Christ", instruction: "We should have the same mindset as Christ, who humbled Himself. In one situation today, choose the humble path Jesus would take." },
  { ref: "Philippians 3:13-14", text: "Brothers, I do not consider myself yet to have taken hold of it. But one thing I do: Forgetting what is behind and straining toward what is ahead, I press on toward the goal to win the prize of God’s heavenly calling in Christ Jesus.", theme: "Pressing on", instruction: "Paul forgot what was behind and pressed on toward the goal. Let go of one past failure today and take one step toward what God is calling you to." },
  { ref: "Philippians 4:4", text: "Rejoice in the Lord always. I will say it again: Rejoice!", theme: "Rejoice always", instruction: "Paul, writing from prison, said rejoice in the Lord always. Find one reason to rejoice in the Lord today, even if circumstances are hard." },
  { ref: "Philippians 4:6-7", text: "Be anxious for nothing, but in everything, by prayer and petition, with thanksgiving, present your requests to God. And the peace of God, which surpasses all understanding, will guard your hearts and your minds in Christ Jesus.", theme: "Prayer instead of worry", instruction: "Instead of worrying, pray about everything with thanksgiving, and God's peace will guard your heart. Turn each worry today into a prayer, and add one thank you to each." },
  { ref: "Philippians 4:8", text: "Finally, brothers, whatever is true, whatever is honorable, whatever is right, whatever is pure, whatever is lovely, whatever is admirable — if anything is excellent or praiseworthy — think on these things.", theme: "Think on these things", instruction: "Fill your mind with what is true, noble, right, pure, lovely and admirable. Replace one negative thought pattern today with something true and good." },
  { ref: "Philippians 4:11", text: "I am not saying this out of need, for I have learned to be content regardless of my circumstances.", theme: "Contentment", instruction: "Paul learned to be content in every situation. Thank God today for what you have, before you think about what you want." },
  { ref: "Philippians 4:13", text: "I can do all things through Christ who gives me strength.", theme: "Strength in Christ", instruction: "Paul could face any situation, plenty or need, through Christ who strengthened him. Face today's difficult situation praying: \"Christ, give me strength for this.\"" },
  { ref: "Philippians 4:19", text: "And my God will supply all your needs according to His glorious riches in Christ Jesus.", theme: "God supplies every need", instruction: "God will meet all our needs according to His riches in Christ. Bring one specific need to God today and trust Him to provide." },
  { ref: "Colossians 1:16-17", text: "For in Him all things were created, things in heaven and on earth, visible and invisible, whether thrones or dominions or rulers or authorities. All things were created through Him and for Him. He is before all things, and in Him all things hold together.", theme: "Christ over all", instruction: "All things were created through Christ and for Him, and in Him all things hold together. When life feels like it is falling apart, thank Jesus that He holds all things together." },
  { ref: "Colossians 2:6-7", text: "Therefore, just as you have received Christ Jesus as Lord, continue to walk in Him, rooted and built up in Him, established in the faith as you were taught, and overflowing with thankfulness.", theme: "Rooted in Him", instruction: "As we received Christ, we should keep walking in Him, rooted and built up. Strengthen your roots today by reading and thinking about one passage about Jesus." },
  { ref: "Colossians 3:2", text: "Set your minds on things above, not on earthly things.", theme: "Minds set above", instruction: "Set your mind on things above, not on earthly things. When your thoughts turn to worry or comparison today, turn them to Christ." },
  { ref: "Colossians 3:12", text: "Therefore, as the elect of God, holy and beloved, clothe yourselves with hearts of compassion, kindness, humility, gentleness, and patience.", theme: "Clothed with compassion", instruction: "As God's chosen people, we clothe ourselves with compassion, kindness, humility, gentleness and patience. Choose one of these \"clothes\" to put on deliberately today." },
  { ref: "Colossians 3:13", text: "Bear with one another and forgive any complaint you may have against someone else. Forgive as the Lord forgave you.", theme: "Bearing with one another", instruction: "Bear with each other and forgive as the Lord forgave you. Forgive one specific offence today and stop replaying it." },
  { ref: "Colossians 3:17", text: "And whatever you do, in word or deed, do it all in the name of the Lord Jesus, giving thanks to God the Father through Him.", theme: "In the name of Jesus", instruction: "Whatever we do in word or deed, we can do in Jesus' name, giving thanks. Pick three tasks today and do each one consciously in Jesus' name." },
  { ref: "Colossians 3:23", text: "Whatever you do, work at it with your whole being, as for the Lord and not for men,", theme: "Working for the Lord", instruction: "Work with all your heart, as working for the Lord, not for people. Do your most boring task today with full effort, as if Jesus were your employer." },
  { ref: "Colossians 4:2", text: "Devote yourselves to prayer, being watchful and thankful,", theme: "Devoted to prayer", instruction: "Devote yourselves to prayer, being watchful and thankful. Keep a short prayer list today and thank God for each answer you notice." },
  { ref: "Colossians 4:6", text: "Let your speech always be gracious, seasoned with salt, so that you may know how to answer everyone.", theme: "Gracious speech", instruction: "Our conversation should be full of grace and seasoned with salt. Speak graciously today in one conversation where you would normally be sharp." },
  { ref: "1 Thessalonians 5:11", text: "Therefore encourage and build one another up, just as you are already doing.", theme: "Building each other up", instruction: "Encourage one another and build each other up. Send a specific encouragement to one believer today, naming what you see God doing in them." },
  { ref: "1 Thessalonians 5:16-18", text: "Rejoice at all times. Pray without ceasing. Give thanks in every circumstance, for this is God’s will for you in Christ Jesus.", theme: "Joy, prayer and thanks", instruction: "Rejoice always, pray continually, and give thanks in all circumstances: this is God's will for you. Set three reminders today: one to rejoice, one to pray, one to give thanks." },
  { ref: "2 Thessalonians 3:3", text: "But the Lord is faithful, and He will strengthen you and guard you from the evil one.", theme: "The Lord is faithful", instruction: "The Lord is faithful; He will strengthen you and protect you from the evil one. Pray today for God's protection over yourself and your family by name." },
  { ref: "1 Timothy 4:12", text: "Let no one despise your youth, but set an example for the believers in speech, in conduct, in love, in faith, in purity.", theme: "An example to others", instruction: "Paul told young Timothy to set an example in speech, conduct, love, faith and purity. Choose one of the five and be a deliberate example in it today." },
  { ref: "1 Timothy 6:6", text: "Of course, godliness with contentment is great gain.", theme: "Godliness with contentment", instruction: "Godliness with contentment is great gain. Resist one purchase or comparison today, and thank God for what you already have." },
  { ref: "1 Timothy 6:12", text: "Fight the good fight of the faith. Take hold of the eternal life to which you were called when you made the good confession before many witnesses.", theme: "Fight the good fight", instruction: "Fight the good fight of faith and take hold of eternal life. Name the area where your faith is being tested, and stand firm with one verse." },
  { ref: "2 Timothy 1:7", text: "For God has not given us a spirit of fear, but of power, love, and self-control.", theme: "Power, love and self-control", instruction: "God did not give us a spirit of fear, but of power, love and self-control. When fear rises today, pray for power, love and self-control by name." },
  { ref: "2 Timothy 2:15", text: "Make every effort to present yourself approved to God, an unashamed workman who accurately handles the word of truth.", theme: "Handling the Word", instruction: "Do your best to be a worker who correctly handles the word of truth. Study one passage carefully today: read the verses around it and ask what it meant to its first readers." },
  { ref: "2 Timothy 3:16-17", text: "All Scripture is God-breathed and is useful for instruction, for conviction, for correction, and for training in righteousness, so that the man of God may be complete, fully equipped for every good work.", theme: "All Scripture is God-breathed", instruction: "All Scripture is God-breathed and useful for teaching, rebuking, correcting and training. Let Scripture correct one specific attitude or habit in you today." },
  { ref: "2 Timothy 4:2", text: "Preach the word; be prepared in season and out of season; reprove, rebuke, and encourage with every form of patient instruction.", theme: "Preach the Word", instruction: "Be ready to share God's word in season and out of season. Prepare one verse you could share, and share it when an opportunity comes today." },
  { ref: "2 Timothy 4:7", text: "I have fought the good fight, I have finished the race, I have kept the faith.", theme: "Keeping the faith", instruction: "At the end of his life Paul could say he had fought well, finished the race and kept the faith. Ask God today to help you finish what He has given you, and stay faithful in it today." },
  { ref: "Titus 2:11-12", text: "For the grace of God has appeared, bringing salvation to everyone. It instructs us to renounce ungodliness and worldly passions, and to live sensible, upright, and godly lives in the present age,", theme: "Grace that teaches", instruction: "God's grace teaches us to say no to ungodliness and to live self-controlled lives. Say no today to one specific temptation, relying on God's grace." },
  { ref: "Titus 3:5", text: "He saved us, not by the righteous deeds we had done, but according to His mercy, through the washing of new birth and renewal by the Holy Spirit.", theme: "Saved by His mercy", instruction: "God saved us because of His mercy, not because of anything good we did. Thank God today for His mercy, and show mercy to someone who does not deserve it." },
  { ref: "Philemon 1:6", text: "I pray that your partnership in the faith may become effective as you fully acknowledge every good thing that is ours in Christ.", theme: "Sharing your faith", instruction: "Paul prayed that sharing their faith would bring a full understanding of every good thing in Christ. Share one thing about your faith with someone today." },
  { ref: "Hebrews 4:12", text: "For the word of God is living and active. Sharper than any double-edged sword, it pierces even to dividing soul and spirit, joints and marrow. It judges the thoughts and intentions of the heart.", theme: "The living Word", instruction: "God's word is living and active, and it reaches our thoughts and the intentions of our heart. As you read today, ask God to show you one hidden attitude it exposes." },
  { ref: "Hebrews 4:16", text: "Let us then approach the throne of grace with confidence, so that we may receive mercy and find grace to help us in our time of need.", theme: "Approach with confidence", instruction: "Because Jesus understands our weakness, we can approach God's throne with confidence for mercy and grace. Come to God today with a specific need, confident that He welcomes you." },
  { ref: "Hebrews 11:1", text: "Now faith is the assurance of what we hope for and the certainty of what we do not see.", theme: "Faith", instruction: "Faith is being sure of what we hope for and certain of what we do not see. Name one thing you are hoping in God for, and thank Him for it as if it were already done." },
  { ref: "Hebrews 11:6", text: "And without faith it is impossible to please God. For anyone who approaches Him must believe that He exists and that He rewards those who earnestly seek Him.", theme: "Faith that pleases God", instruction: "Without faith it is impossible to please God; we must believe He exists and rewards those who seek Him. Seek God earnestly today, believing He will meet you." },
  { ref: "Hebrews 12:1-2", text: "Therefore, since we are surrounded by such a great cloud of witnesses, let us throw off every encumbrance and the sin that so easily entangles, and let us run with endurance the race set out for us. Let us fix our eyes on Jesus, the author and perfecter of our faith, who for the joy set before Him endured the cross, scorning its shame, and sat down at the right hand of the throne of God.", theme: "Running the race", instruction: "We run our race by throwing off what hinders us and fixing our eyes on Jesus. Identify one thing that slows you down spiritually and put it aside today." },
  { ref: "Hebrews 12:11", text: "No discipline seems enjoyable at the time, but painful. Later on, however, it yields a harvest of righteousness and peace to those who have been trained by it.", theme: "Discipline that trains", instruction: "God's discipline is painful at the time, but later produces righteousness and peace. If you are being corrected, ask God what He is teaching you instead of resisting it." },
  { ref: "Hebrews 13:5", text: "Keep your lives free from the love of money and be content with what you have, for God has said: “Never will I leave you, never will I forsake you.”", theme: "Never alone", instruction: "God has said, \"I will never leave you nor forsake you.\" When you feel alone today, read this promise aloud." },
  { ref: "Hebrews 13:8", text: "Jesus Christ is the same yesterday and today and forever.", theme: "Jesus never changes", instruction: "Jesus Christ is the same yesterday, today and forever. Remember one thing Jesus did in the Gospels, and trust that He is the same for you today." },
  { ref: "Hebrews 13:16", text: "And do not neglect to do good and to share with others, for with such sacrifices God is pleased.", theme: "Doing good and sharing", instruction: "Doing good and sharing with others are sacrifices that please God. Share something today, food, money or time, with someone who needs it." },
  { ref: "James 1:2-3", text: "Consider it pure joy, my brothers, when you encounter trials of many kinds, because you know that the testing of your faith develops perseverance.", theme: "Joy in trials", instruction: "Trials test our faith and produce perseverance, so we can count them as joy. Ask God what perseverance He is building in you through your current trial." },
  { ref: "James 1:5", text: "Now if any of you lacks wisdom, he should ask God, who gives generously to all without finding fault, and it will be given to him.", theme: "Asking for wisdom", instruction: "If we lack wisdom, we can ask God, who gives generously without finding fault. Ask God today for wisdom in one specific decision, and expect His help." },
  { ref: "James 1:19", text: "My beloved brothers, understand this: Everyone should be quick to listen, slow to speak, and slow to anger,", theme: "Quick to listen", instruction: "Be quick to listen, slow to speak and slow to become angry. In your conversations today, listen fully before you respond." },
  { ref: "James 1:22", text: "Be doers of the word, and not hearers only. Otherwise, you are deceiving yourselves.", theme: "Doers of the Word", instruction: "Do not merely listen to the word and deceive yourself; do what it says. Choose one instruction from what you read today and obey it before tonight." },
  { ref: "James 2:17", text: "So too, faith by itself, if it does not result in action, is dead.", theme: "Faith that acts", instruction: "Faith that does nothing is dead. Put your faith into action today by helping someone in a practical way." },
  { ref: "James 4:7-8", text: "Submit yourselves, then, to God. Resist the devil, and he will flee from you. Draw near to God, and He will draw near to you. Cleanse your hands, you sinners, and purify your hearts, you double-minded.", theme: "Draw near to God", instruction: "Submit to God, resist the devil, and draw near to God, and He will draw near to you. Resist one temptation today and spend time drawing near to God in prayer." },
  { ref: "James 4:10", text: "Humble yourselves before the Lord, and He will exalt you.", theme: "Humbled before God", instruction: "Humble yourselves before the Lord, and He will lift you up. Admit one area of pride to God today, and let Him lift you rather than promoting yourself." },
  { ref: "James 5:16", text: "Therefore confess your sins to each other and pray for each other so that you may be healed. The prayer of a righteous man has great power to prevail.", theme: "Praying for one another", instruction: "Confess sins to each other and pray for each other so that you may be healed. Pray today for one person in your group by name and for their specific need." },
  { ref: "1 Peter 2:9", text: "But you are a chosen people, a royal priesthood, a holy nation, a people for God’s own possession, to proclaim the virtues of Him who called you out of darkness into His marvelous light.", theme: "A chosen people", instruction: "God called us out of darkness into His wonderful light to declare His praises. Tell someone today one specific thing God has done for you." },
  { ref: "1 Peter 3:15", text: "But in your hearts sanctify Christ as Lord. Always be prepared to give a defense to everyone who asks you the reason for the hope that is in you. But respond with gentleness and respect,", theme: "Ready to give an answer", instruction: "Always be ready to explain the hope you have, with gentleness and respect. Write a short, simple answer to \"Why do you follow Jesus?\" and practise saying it." },
  { ref: "1 Peter 4:8", text: "Above all, love one another deeply, because love covers over a multitude of sins.", theme: "Love covers", instruction: "Love one another deeply, because love covers a multitude of sins. Choose to overlook one small offence today out of love." },
  { ref: "1 Peter 4:10", text: "As good stewards of the manifold grace of God, each of you should use whatever gift he has received to serve one another.", theme: "Using your gifts", instruction: "Each of us has received a gift to use in serving others. Name one gift God has given you and use it to serve someone today." },
  { ref: "1 Peter 5:7", text: "Cast all your anxiety on Him, because He cares for you.", theme: "Cast your cares", instruction: "Cast all your anxiety on God because He cares for you. Name your biggest anxiety today and give it to God in a short prayer each time it returns." },
  { ref: "1 Peter 5:8-9", text: "Be sober-minded and alert. Your adversary the devil prowls around like a roaring lion, seeking someone to devour. Resist him, standing firm in your faith and in the knowledge that your brothers throughout the world are undergoing the same kinds of suffering.", theme: "Alert and firm", instruction: "The devil prowls like a lion, so be alert and resist him, standing firm in the faith. Notice where you are most vulnerable today, and stand firm there with prayer." },
  { ref: "2 Peter 1:5-7", text: "For this very reason, make every effort to add to your faith virtue; and to virtue, knowledge; and to knowledge, self-control; and to self-control, perseverance; and to perseverance, godliness; and to godliness, brotherly kindness; and to brotherly kindness, love.", theme: "Growing in faith", instruction: "Peter lists qualities to add to our faith: goodness, knowledge, self-control, perseverance, godliness, kindness and love. Pick one quality and practise it on purpose today." },
  { ref: "2 Peter 3:18", text: "But grow in the grace and knowledge of our Lord and Savior Jesus Christ. To Him be the glory both now and to the day of eternity. Amen.", theme: "Growing in grace", instruction: "We are to grow in the grace and knowledge of Jesus Christ. Learn one new thing about Jesus today from the Gospels." },
  { ref: "1 John 1:7", text: "But if we walk in the light as He is in the light, we have fellowship with one another, and the blood of Jesus His Son cleanses us from all sin.", theme: "Walking in the light", instruction: "Walking in the light means living openly before God and others. Share honestly with a trusted believer today how you are really doing." },
  { ref: "1 John 1:9", text: "If we confess our sins, He is faithful and just to forgive us our sins and to cleanse us from all unrighteousness.", theme: "Confession and forgiveness", instruction: "If we confess our sins, God is faithful and just to forgive us and cleanse us. Confess specific sins to God today, and thank Him that you are forgiven." },
  { ref: "1 John 3:1", text: "Behold what manner of love the Father has given to us, that we should be called children of God. And that is what we are! The reason the world does not know us is that it did not know Him.", theme: "Children of God", instruction: "The Father has lavished His love on us by calling us His children. Thank God today that you belong to His family." },
  { ref: "1 John 3:18", text: "Little children, let us love not in word and speech, but in action and truth.", theme: "Love in action", instruction: "Love is shown by actions and truth, not just words. Show love today through one practical action, not only kind words." },
  { ref: "1 John 4:7", text: "Beloved, let us love one another, because love comes from God. Everyone who loves has been born of God and knows God.", theme: "Love comes from God", instruction: "Love comes from God, and everyone who loves has been born of God. Love one difficult person today as a sign that you belong to God." },
  { ref: "1 John 4:18", text: "There is no fear in love, but perfect love drives out fear, because fear involves punishment. The one who fears has not been perfected in love.", theme: "Perfect love casts out fear", instruction: "God's perfect love drives out fear. Bring your fear of punishment or rejection to God today and rest in His love." },
  { ref: "1 John 4:19", text: "We love because He first loved us.", theme: "We love because He first loved us", instruction: "We love because God first loved us. Thank God for loving you first, and pass that love on to someone today." },
  { ref: "1 John 5:14", text: "And this is the confidence that we have before Him: If we ask anything according to His will, He hears us.", theme: "Confidence in prayer", instruction: "If we ask anything according to God's will, He hears us. Pray today for something you know is God's will, like wisdom or a person's salvation." },
  { ref: "Jude 1:24-25", text: "Now to Him who is able to keep you from stumbling and to present you unblemished in His glorious presence, with great joy — to the only God our Savior be glory, majesty, dominion, and authority through Jesus Christ our Lord before all time, and now, and for all eternity. Amen.", theme: "Able to keep you", instruction: "God is able to keep us from stumbling and to present us faultless before Him with joy. Thank God today that your faithfulness depends on His power, not only yours." },
  { ref: "Revelation 3:20", text: "Behold, I stand at the door and knock. If anyone hears My voice and opens the door, I will come in and dine with him, and he with Me.", theme: "Opening the door", instruction: "Jesus stands at the door and knocks, wanting to share a meal with whoever opens. Spend unhurried time with Jesus today, as you would with a guest at your table." },
  { ref: "Revelation 21:4", text: "‘He will wipe away every tear from their eyes,’ and there will be no more death or mourning or crying or pain, for the former things have passed away.”", theme: "No more tears", instruction: "God will wipe away every tear, and there will be no more death, mourning or pain. If you are grieving, read this verse today and hold on to that future." },
  { ref: "Revelation 21:5", text: "And the One seated on the throne said, “Behold, I make all things new.” Then He said, “Write this down, for these words are faithful and true.”", theme: "All things new", instruction: "God says, \"I am making everything new.\" Bring one broken situation to God today and ask Him to bring newness to it." },
  { ref: "Revelation 22:20", text: "He who testifies to these things says, “Yes, I am coming soon.” Amen. Come, Lord Jesus!", theme: "Come, Lord Jesus", instruction: "Jesus promises, \"I am coming soon,\" and the church answers, \"Come, Lord Jesus.\" Live today as someone ready for Jesus' return, putting right one thing you would want to be right." },
  { ref: "Genesis 2:15", text: "Then the LORD God took the man and placed him in the Garden of Eden to cultivate and keep it.", theme: "Caring for creation", instruction: "God placed Adam in the garden to work it and take care of it. Care well today for something God has entrusted to you: your home, work or the natural world." },
  { ref: "Genesis 28:15", text: "Look, I am with you, and I will watch over you wherever you go, and I will bring you back to this land. For I will not leave you until I have done what I have promised you.”", theme: "God keeps watch", instruction: "God promised Jacob, \"I am with you and will watch over you wherever you go.\" Wherever you go today, remind yourself that God is watching over you there." },
  { ref: "Exodus 15:2", text: "The LORD is my strength and my song, and He has become my salvation. He is my God, and I will praise Him, my father’s God, and I will exalt Him.", theme: "My strength and song", instruction: "After crossing the sea, Moses sang that the Lord is his strength and his song. Sing a song of praise to God today for something He has rescued you from." },
  { ref: "Psalms 9:10", text: "Those who know Your name trust in You, for You, O LORD, have not forsaken those who seek You.", theme: "Trusting those who seek Him", instruction: "Those who know God's name trust Him, because He never forsakes those who seek Him. Learn one of God's names in Scripture today, and trust Him by that name." },
  { ref: "Psalms 30:5", text: "For His anger is fleeting, but His favor lasts a lifetime. Weeping may stay the night, but joy comes in the morning.", theme: "Joy in the morning", instruction: "Weeping may last through the night, but joy comes in the morning. If you are in a sorrowful season, tell God how you feel and hold on to the morning He promises." },
  { ref: "Psalms 40:1", text: "For the choirmaster. A Psalm of David. I waited patiently for the LORD; He inclined to me and heard my cry.", theme: "Waiting patiently", instruction: "David waited patiently for the Lord, and the Lord turned and heard his cry. Keep waiting patiently on God today for the prayer that has not yet been answered." },
  { ref: "Psalms 68:6", text: "God settles the lonely in families; He leads the prisoners out to prosperity, but the rebellious dwell in a sun-scorched land.", theme: "God sets the lonely in families", instruction: "God places the lonely in families. Invite someone who may be lonely to share a meal or time with you this week." },
  { ref: "Psalms 85:8", text: "I will listen to what God the LORD will say; for He will surely speak peace to His people and His saints; He will not let them return to folly.", theme: "Listening for peace", instruction: "David listened for what the Lord would say, and God spoke peace to His people. Spend ten minutes today listening in prayer, and write down what you sense from His Word." },
  { ref: "Psalms 112:7", text: "He does not fear bad news; his heart is steadfast, trusting in the LORD.", theme: "Not afraid of bad news", instruction: "The righteous do not fear bad news because their hearts trust the Lord. When bad news comes today, pray before you react." },
  { ref: "Proverbs 10:12", text: "Hatred stirs up dissension, but love covers all transgressions.", theme: "Love covers wrongs", instruction: "Hatred stirs up conflict, but love covers over all wrongs. Choose not to bring up an old offence today, and cover it with love." },
  { ref: "Proverbs 19:17", text: "Kindness to the poor is a loan to the LORD, and He will repay the lender.", theme: "Kindness to the poor", instruction: "Whoever is kind to the poor lends to the Lord, and He will repay. Give something today to someone in need, trusting God to repay." },
  { ref: "Isaiah 30:15", text: "For the Lord GOD, the Holy One of Israel, has said: “By repentance and rest you would be saved; your strength would lie in quiet confidence — but you were not willing.”", theme: "Strength in quietness", instruction: "God told Israel their strength would be in quietness and trust, but they refused. Instead of rushing to fix a problem today, pray quietly and trust God first." },
  { ref: "Isaiah 49:15-16", text: "“Can a woman forget her nursing child, or lack compassion for the son of her womb? Even if she could forget, I will not forget you! Behold, I have inscribed you on the palms of My hands; your walls are ever before Me.", theme: "Never forgotten", instruction: "God will never forget His people; their names are engraved on His hands. When you feel forgotten today, read this verse and thank God that He remembers you." },
  { ref: "Isaiah 64:8", text: "But now, O LORD, You are our Father; we are the clay, and You are the potter; we are all the work of Your hand.", theme: "The Potter", instruction: "God is the potter and we are the clay, the work of His hands. Ask God today to shape you through the difficult thing you are going through." },
  { ref: "Matthew 5:8", text: "Blessed are the pure in heart, for they will see God.", theme: "Pure in heart", instruction: "The pure in heart will see God. Remove one thing from your life today that clouds your heart: a show, a habit or a grudge." },
  { ref: "Matthew 9:36", text: "When He saw the crowds, He was moved with compassion for them, because they were harassed and helpless, like sheep without a shepherd.", theme: "Compassion for the crowds", instruction: "Jesus saw the crowds and felt compassion, because they were like sheep without a shepherd. Look at the people around you today and ask God to give you His compassion for them." },
  { ref: "Matthew 13:23", text: "But the seed sown on good soil is the one who hears the word and understands it. He indeed bears fruit and produces a crop — a hundredfold, sixtyfold, or thirtyfold.”", theme: "Good soil", instruction: "The seed that falls on good soil is the person who hears the word, understands it and bears fruit. Read a passage today until you understand it, then do what it says." },
  { ref: "Mark 4:39", text: "Then Jesus got up and rebuked the wind and the sea. “Silence!” He commanded. “Be still!” And the wind died down, and it was perfectly calm.", theme: "Peace in the storm", instruction: "Jesus spoke to the storm and it became completely calm. Bring the storm in your life to Jesus today and trust His authority over it." },
  { ref: "Luke 6:45", text: "The good man brings good things out of the good treasure of his heart, and the evil man brings evil things out of the evil treasure of his heart. For out of the overflow of the heart the mouth speaks.", theme: "Words from the heart", instruction: "What we say comes from what fills our heart. Notice your words today and ask what they reveal about your heart." },
  { ref: "Luke 22:42", text: "“Father, if You are willing, take this cup from Me. Yet not My will, but Yours be done.”", theme: "Your will be done", instruction: "In Gethsemane, Jesus prayed, \"Not my will, but Yours be done.\" Pray this prayer today about one decision or situation." },
  { ref: "John 2:5", text: "His mother said to the servants, “Do whatever He tells you.”", theme: "Do whatever He tells you", instruction: "Mary told the servants, \"Do whatever He tells you,\" and Jesus turned water into wine. Do today the one thing you sense Jesus has been telling you to do." },
  { ref: "John 4:35", text: "Do you not say, ‘There are still four months until the harvest’? I tell you, lift up your eyes and look at the fields, for they are ripe for harvest.", theme: "Fields ready for harvest", instruction: "Jesus told His disciples to look up and see that the fields are ready for harvest. Look around today for someone who may be open to hearing about Jesus." },
  { ref: "John 6:68", text: "Simon Peter replied, “Lord, to whom would we go? You have the words of eternal life.", theme: "Words of eternal life", instruction: "When others left, Peter said, \"Lord, to whom shall we go? You have the words of eternal life.\" When other voices pull at you today, return to the words of Jesus." },
  { ref: "John 12:26", text: "If anyone serves Me, he must follow Me; and where I am, My servant will be as well. If anyone serves Me, the Father will honor him.", theme: "Serving and following", instruction: "Whoever serves Jesus must follow Him, and the Father will honour them. Serve Jesus today in a hidden way, without seeking recognition." },
  { ref: "Acts 3:19", text: "Repent, then, and turn back, so that your sins may be wiped away,", theme: "Times of refreshing", instruction: "Repenting and turning to God brings times of refreshing from the Lord. Turn from one sin today and ask God for His refreshing." },
  { ref: "Acts 9:31", text: "Then the church throughout Judea, Galilee, and Samaria experienced a time of peace. It grew in strength and numbers, living in the fear of the Lord and the encouragement of the Holy Spirit.", theme: "Strengthened and encouraged", instruction: "The church grew as it lived in the fear of the Lord and the encouragement of the Holy Spirit. Encourage your church or group today by your faithfulness and kind words." },
  { ref: "Romans 13:8", text: "Be indebted to no one, except to one another in love. For he who loves his neighbor has fulfilled the law.", theme: "The debt of love", instruction: "The only debt we should keep owing is the debt to love one another. Show love today to someone you feel you owe nothing to." },
  { ref: "Romans 14:19", text: "So then, let us pursue what leads to peace and to mutual edification.", theme: "Pursuing peace", instruction: "Make every effort to do what leads to peace and mutual building up. Avoid one argument today that would not build anyone up." },
  { ref: "1 Corinthians 3:6", text: "I planted the seed and Apollos watered it, but God made it grow.", theme: "God gives the growth", instruction: "Paul planted, Apollos watered, but God gave the growth. Do your part today in helping someone grow, and trust God for the results." },
  { ref: "1 Corinthians 12:27", text: "Now you are the body of Christ, and each of you is a member of it.", theme: "One body", instruction: "We are the body of Christ, and each of us is a part of it. Tell one member of your church or group today how they help the body." },
  { ref: "2 Corinthians 3:18", text: "And we, who with unveiled faces all reflect the glory of the Lord, are being transformed into His image with intensifying glory, which comes from the Lord, who is the Spirit.", theme: "Being transformed", instruction: "As we look at the Lord's glory, we are being transformed into His image. Spend time today looking at Jesus in a Gospel passage, and ask Him to make you more like Him." },
  { ref: "Ephesians 1:3", text: "Blessed be the God and Father of our Lord Jesus Christ, who has blessed us in Christ with every spiritual blessing in the heavenly realms.", theme: "Every spiritual blessing", instruction: "God has blessed us in Christ with every spiritual blessing. Read Ephesians 1:3-14 today and list the blessings you find." },
  { ref: "Philippians 2:14-15", text: "Do everything without complaining or arguing, so that you may be blameless and pure, children of God without fault in a crooked and perverse generation, in which you shine as lights in the world", theme: "Shining without complaint", instruction: "Doing everything without grumbling helps us shine like stars in a crooked world. Go through today without complaining once, and notice how it changes you." },
  { ref: "Colossians 1:10", text: "so that you may walk in a manner worthy of the Lord and may please Him in every way: bearing fruit in every good work, growing in the knowledge of God,", theme: "A worthy life", instruction: "Paul prayed that believers would live a life worthy of the Lord and pleasing to Him. Ask God today how you can please Him in your work or relationships." },
  { ref: "1 Thessalonians 4:11", text: "and to aspire to live quietly, to attend to your own matters, and to work with your own hands, as we instructed you.", theme: "A quiet life", instruction: "Make it your ambition to lead a quiet life, mind your own business and work with your hands. Do your work faithfully today without seeking attention or gossiping." },
  { ref: "Hebrews 3:13", text: "But exhort one another daily, as long as it is called today, so that none of you may be hardened by sin’s deceitfulness.", theme: "Encouraging daily", instruction: "Encourage one another daily, so that no one is hardened by sin's deceitfulness. Encourage someone today who may be drifting from God." },
  { ref: "Hebrews 10:23", text: "Let us hold resolutely to the hope we profess, for He who promised is faithful.", theme: "Holding fast to hope", instruction: "Hold firmly to the hope we profess, because God who promised is faithful. Write down one of God's promises and hold on to it today." },
  { ref: "James 3:17", text: "But the wisdom from above is first of all pure, then peace-loving, gentle, accommodating, full of mercy and good fruit, impartial, and sincere.", theme: "Wisdom from above", instruction: "Wisdom from God is pure, peace-loving, considerate and full of mercy. Before you give advice today, check if it has these qualities." },
  { ref: "1 Peter 1:3", text: "Blessed be the God and Father of our Lord Jesus Christ! By His great mercy He has given us new birth into a living hope through the resurrection of Jesus Christ from the dead,", theme: "A living hope", instruction: "Because Jesus rose from the dead, we have been born again into a living hope. Thank God today for the living hope you have because Jesus is alive." },
  { ref: "1 John 2:6", text: "Whoever claims to abide in Him must walk as Jesus walked.", theme: "Walking as Jesus walked", instruction: "Whoever says they live in Jesus must live as He lived. In one situation today, ask: \"How did Jesus treat people?\" and do the same." },
  { ref: "Revelation 1:8", text: "“I am the Alpha and the Omega,” says the Lord God, who is and was and is to come — the Almighty.", theme: "The Alpha and Omega", instruction: "God is the Alpha and Omega, the beginning and the end, the Almighty. Worship God today as the One who holds both your past and your future." },
  { ref: "Psalms 136:1", text: "Give thanks to the LORD, for He is good. His loving devotion endures forever.", theme: "His love endures forever", instruction: "Every line of this psalm repeats that God's love endures forever. Read Psalm 136 today and add one line about your own life, ending with \"His love endures forever.\"" },
  { ref: "Isaiah 12:2", text: "Surely God is my salvation; I will trust and not be afraid. For the LORD GOD is my strength and my song, and He also has become my salvation.”", theme: "God my salvation", instruction: "God is my salvation; I will trust and not be afraid, because the Lord is my strength and song. Say this verse aloud today when you feel afraid." },
  { ref: "Matthew 5:6", text: "Blessed are those who hunger and thirst for righteousness, for they will be filled.", theme: "Hungering for righteousness", instruction: "Those who hunger and thirst for righteousness will be filled. Ask God today to make you hungry for what is right, and act rightly in one situation." },
  { ref: "Luke 17:15-16", text: "When one of them saw that he was healed, he came back, praising God in a loud voice. He fell facedown at Jesus’ feet in thanksgiving to Him — and he was a Samaritan.", theme: "Returning to give thanks", instruction: "Of ten men healed, only one came back to thank Jesus. Go back and thank God today for an answered prayer you never thanked Him for." },
  { ref: "John 13:14-15", text: "So if I, your Lord and Teacher, have washed your feet, you also should wash one another’s feet. I have set you an example so that you should do as I have done for you.", theme: "Washing feet", instruction: "Jesus washed His disciples' feet and told them to do the same for each other. Serve someone today in a humble, practical task that others avoid." },
  { ref: "Acts 2:46-47", text: "With one accord they continued to meet daily in the temple courts and to break bread from house to house, sharing their meals with gladness and sincerity of heart, praising God and enjoying the favor of all the people. And the Lord added to their number daily those who were being saved.", theme: "Glad and sincere hearts", instruction: "The early believers met together, shared meals with glad and sincere hearts, and praised God. Share a meal or time with believers this week." },
  { ref: "2 Corinthians 13:14", text: "The grace of the Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit be with all of you.", theme: "Grace, love and fellowship", instruction: "Paul blessed the church with the grace of Jesus, the love of God and the fellowship of the Holy Spirit. Pray this blessing today over each person in your group by name." },
  { ref: "Proverbs 14:31", text: "Whoever oppresses the poor taunts their Maker, but whoever is kind to the needy honors Him.", theme: "Honouring God through kindness", instruction: "Whoever is kind to the needy honours God. Do one act of kindness today for someone who is poor, and see it as honouring God." },
  { ref: "Psalms 119:18", text: "Open my eyes that I may see wondrous things from Your law.", theme: "Open my eyes", instruction: "The psalmist asked God to open his eyes to see wonderful things in His law. Pray this verse before you read the Bible today, and write down one thing you notice." },
  { ref: "Isaiah 50:4", text: "The Lord GOD has given Me the tongue of discipleship, to sustain the weary with a word. He awakens Me morning by morning; He awakens My ear to listen as a disciple.", theme: "A word for the weary", instruction: "The servant of the Lord was given an instructed tongue to sustain the weary, and listened to God every morning. Listen to God this morning, then speak one sustaining word to someone who is weary." },
  { ref: "Matthew 14:27", text: "But Jesus spoke up at once: “Take courage! It is I. Do not be afraid.”", theme: "Take courage", instruction: "When the disciples were terrified in the storm, Jesus said, \"Take courage! It is I. Do not be afraid.\" In today's fear, hear Jesus saying these words to you." },
  { ref: "Luke 12:32", text: "Do not be afraid, little flock, for your Father is pleased to give you the kingdom.", theme: "Do not be afraid, little flock", instruction: "Jesus told His small flock not to be afraid, because the Father is pleased to give them the kingdom. Rest today in the Father's good pleasure toward you, and let go of one fear." },
  { ref: "Romans 15:7", text: "Accept one another, then, just as Christ accepted you, in order to bring glory to God.", theme: "Accepting one another", instruction: "Accept one another just as Christ accepted you, to bring praise to God. Welcome someone today who is different from you, as Christ welcomed you." },
];
